// bus/schema.t27 — Event Type Definitions
// Core event types and structures for the event bus
// φ² + 1/φ² = 3 | TRINITY

module bus-schema;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;

// ============================================================================
// Constants
// ============================================================================

/// Default event bus channel size
pub const DEFAULT_CHANNEL_SIZE : usize = 1000;

/// Maximum event payload size in bytes
pub const MAX_PAYLOAD_SIZE : usize = 1048576;

/// Default subscriber buffer size
pub const DEFAULT_SUBSCRIBER_BUFFER : usize = 100;

/// Maximum number of subscribers per topic
pub const MAX_SUBSCRIBERS_PER_TOPIC : usize = 100;

/// Default event TTL in milliseconds
pub const DEFAULT_EVENT_TTL_MS : usize = 60000;

/// Wildcard topic pattern
pub const WILDCARD_TOPIC : [1]u8 = "*";

/// Topic separator
pub const TOPIC_SEPARATOR : [1]u8 = "/";

// ============================================================================
// Types
// ============================================================================

/// Event type
pub const EventType = enum(u8) {
    lsp_request = 0,
    lsp_response = 1,
    lsp_notification = 2,
    provider_request = 3,
    provider_response = 4,
    provider_stream_start = 5,
    provider_stream_chunk = 6,
    provider_stream_end = 7,
    provider_stream_error = 8,
    system_error = 9,
    system_info = 10,
    custom = 11,
};

/// Event priority
pub const EventPriority = enum(u8) {
    low = 0,
    normal = 1,
    high = 2,
    urgent = 3,
};

/// Event
pub const Event = struct {
    id : usize,
    type : EventType,
    topic : []u8,
    payload : []u8,
    timestamp : usize,
    priority : EventPriority,
    ttl_ms : usize,
};

/// Event filter
pub const EventFilter = struct {
    event_types : []EventType,
    topics : [][]u8,
    min_priority : EventPriority,
};

/// Event result
pub const EventResult = struct {
    success : bool,
    error : []u8,
};

/// Event batch
pub const EventBatch = struct {
    events : []Event,
    batch_id : usize,
};

/// Event metadata
pub const EventMetadata = struct {
    source : []u8,
    correlation_id : []u8,
    reply_to : []u8,
};

/// Topic pattern
pub const TopicPattern = struct {
    pattern : []u8,
    is_wildcard : bool,
};

/// Event stats
pub const EventStats = struct {
    events_published : usize,
    events_delivered : usize,
    events_dropped : usize,
    subscribers_count : usize,
    topics_count : usize,
};

/// Bus state
pub const BusState = enum(u8) {
    stopped = 0,
    starting = 1,
    running = 2,
    stopping = 3,
    error = 4,
};

/// Bus configuration
pub const BusConfig = struct {
    channel_size : usize,
    max_payload_size : usize,
    default_ttl_ms : usize,
    enable_metrics : bool,
};

/// Event acknowledgment
pub const EventAck = enum(u8) {
    none = 0,
    received = 1,
    processed = 2,
    failed = 3,
};

/// Delivery mode
pub const DeliveryMode = enum(u8) {
    fire_and_forget = 0,
    at_least_once = 1,
    exactly_once = 2,
};

/// Subscription
pub const Subscription = struct {
    id : usize,
    topic_pattern : TopicPattern,
    handler : []u8,
    filter : EventFilter,
    delivery_mode : DeliveryMode,
    buffer_size : usize,
};

/// Subscription info
pub const SubscriptionInfo = struct {
    subscription_id : usize,
    subscriber_id : []u8,
    topic : []u8,
    created_at : usize,
};

/// Unsubscription result
pub const UnsubscribeResult = struct {
    success : bool,
    subscriptions_removed : usize,
    error : []u8,
};

/// Bus error
pub const BusError = struct {
    code : i32,
    message : []u8,
    event_id : usize,
};

// ============================================================================
// Functions
// ============================================================================

/// Create event
pub fn event_create(event_type: EventType, topic: []u8, payload: []u8) Event {
    return Event{
        .id = 0,
        .type = event_type,
        .topic = topic,
        .payload = payload,
        .timestamp = 0,
        .priority = .normal,
        .ttl_ms = DEFAULT_EVENT_TTL_MS,
    };
}

/// Create event with priority
pub fn event_with_priority(event_type: EventType, topic: []u8, payload: []u8, priority: EventPriority) Event {
    return Event{
        .id = 0,
        .type = event_type,
        .topic = topic,
        .payload = payload,
        .timestamp = 0,
        .priority = priority,
        .ttl_ms = DEFAULT_EVENT_TTL_MS,
    };
}

/// Create event filter
pub fn event_filter_create(topics: [][]u8, min_priority: EventPriority) EventFilter {
    return EventFilter{
        .event_types = &[_]EventType{},
        .topics = topics,
        .min_priority = min_priority,
    };
}

/// Create event result
pub fn event_result_create(success: bool) EventResult {
    return EventResult{
        .success = success,
        .error = "",
    };
}

/// Create event result with error
pub fn event_result_error(message: []u8) EventResult {
    return EventResult{
        .success = false,
        .error = message,
    };
}

/// Create topic pattern
pub fn topic_pattern_create(pattern: []u8) TopicPattern {
    return TopicPattern{
        .pattern = pattern,
        .is_wildcard = pattern == WILDCARD_TOPIC,
    };
}

/// Create bus config
pub fn bus_config_default() BusConfig {
    return BusConfig{
        .channel_size = DEFAULT_CHANNEL_SIZE,
        .max_payload_size = MAX_PAYLOAD_SIZE,
        .default_ttl_ms = DEFAULT_EVENT_TTL_MS,
        .enable_metrics = true,
    };
}

/// Create subscription
pub fn subscription_create(topic_pattern: []u8, handler: []u8) Subscription {
    return Subscription{
        .id = 0,
        .topic_pattern = topic_pattern_create(topic_pattern),
        .handler = handler,
        .filter = event_filter_create(&[_][]u8{}, .low),
        .delivery_mode = .fire_and_forget,
        .buffer_size = DEFAULT_SUBSCRIBER_BUFFER,
    };
}

/// Create subscription info
pub fn subscription_info_create(subscription_id: usize, subscriber_id: []u8, topic: []u8) SubscriptionInfo {
    return SubscriptionInfo{
        .subscription_id = subscription_id,
        .subscriber_id = subscriber_id,
        .topic = topic,
        .created_at = 0,
    };
}

/// Create unsubscription result
pub fn unsubscribe_result_create(success: bool, removed: usize) UnsubscribeResult {
    return UnsubscribeResult{
        .success = success,
        .subscriptions_removed = removed,
        .error = "",
    };
}

/// Create bus error
pub fn bus_error_create(code: i32, message: []u8) BusError {
    return BusError{
        .code = code,
        .message = message,
        .event_id = 0,
    };
}

/// Create event stats
pub fn event_stats_create() EventStats {
    return EventStats{
        .events_published = 0,
        .events_delivered = 0,
        .events_dropped = 0,
        .subscribers_count = 0,
        .topics_count = 0,
    };
}

/// Get event type string
pub fn event_type_to_string(event_type: EventType) []u8 {
    return switch (event_type) {
        .lsp_request => "lsp_request",
        .lsp_response => "lsp_response",
        .lsp_notification => "lsp_notification",
        .provider_request => "provider_request",
        .provider_response => "provider_response",
        .provider_stream_start => "provider_stream_start",
        .provider_stream_chunk => "provider_stream_chunk",
        .provider_stream_end => "provider_stream_end",
        .provider_stream_error => "provider_stream_error",
        .system_error => "system_error",
        .system_info => "system_info",
        .custom => "custom",
    };
}

/// Get priority string
pub fn priority_to_string(priority: EventPriority) []u8 {
    return switch (priority) {
        .low => "low",
        .normal => "normal",
        .high => "high",
        .urgent => "urgent",
    };
}

/// Check if topic pattern is wildcard
pub fn is_wildcard_pattern(pattern: TopicPattern) bool {
    return pattern.is_wildcard;
}

/// Check if topic matches pattern
pub fn topic_matches_pattern(topic: []u8, pattern: TopicPattern) bool {
    if (pattern.is_wildcard) {
        return true;
    }
    return topic == pattern.pattern;
}

/// Check if event matches filter
pub fn event_matches_filter(event: Event, filter: EventFilter) bool {
    var matches_type = false;
    for (filter.event_types) |et| {
        if (event.type == et) {
            matches_type = true;
        }
    }
    if (filter.event_types.len == 0) {
        matches_type = true;
    }

    var matches_topic = false;
    for (filter.topics) |topic| {
        if (event.topic == topic) {
            matches_topic = true;
        }
    }
    if (filter.topics.len == 0) {
        matches_topic = true;
    }

    const matches_priority = event.priority >= filter.min_priority;
    return matches_type and matches_topic and matches_priority;
}

/// Check if bus is running
pub fn is_bus_running(state: BusState) bool {
    return state == .running;
}

/// Get bus state string
pub fn bus_state_to_string(state: BusState) []u8 {
    return switch (state) {
        .stopped => "stopped",
        .starting => "starting",
        .running => "running",
        .stopping => "stopping",
        .error => "error",
    };
}

/// Check if payload size is valid
pub fn is_payload_valid(size: usize) bool {
    return size <= MAX_PAYLOAD_SIZE;
}

