// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_deque.t27
// Ternary Deque Operations Specification
// Ring 088 - Double-ended queue operations for ternary data
// Defines deque with push/pop from both ends
// phi^2 + 1/phi^2 = 3 | TRINITY

module TernaryDeque {
    use base::types;

    // =====================================================
    // 1. Deque Constants
    // =========================================================================

    // Trit values
    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // Deque limits
    const DEQUE_MAX_SIZE : usize = 27;

    // =====================================================
    // 2. Deque Structure (Circular Buffer)
    // =========================================================================

    // deque_init(data: []i32, front: *usize, back: *usize, count: *usize) -> void
    // Initialize empty deque
    fn deque_init(data: []i32, front: *usize, back: *usize, count: *usize) -> void {
        var i : usize = 0;
        while (i < DEQUE_MAX_SIZE and i < data.len) {
            data[i] = TRIT_ZERO;
            i = i + 1;
        }
        front.* = 0;
        back.* = 0;
        count.* = 0;
    }

    // deque_push_front(data: []i32, front: *usize, back: *usize, count: *usize, value: i32) -> bool
    // Add element to front of deque
    fn deque_push_front(data: []i32, front: *usize, back: *usize, count: *usize, value: i32) -> bool {
        if (count.* >= DEQUE_MAX_SIZE) {
            return false;
        }

        if (count.* > 0) {
            if (front.* == 0) {
                front.* = DEQUE_MAX_SIZE - 1;
            } else {
                front.* = front.* - 1;
            }
        }

        if (front.* < data.len) {
            data[front.*] = value;
        }
        count.* = count.* + 1;
        return true;
    }

    // deque_push_back(data: []i32, front: *usize, back: *usize, count: *usize, value: i32) -> bool
    // Add element to back of deque
    fn deque_push_back(data: []i32, front: *usize, back: *usize, count: *usize, value: i32) -> bool {
        if (count.* >= DEQUE_MAX_SIZE) {
            return false;
        }

        if (back.* < data.len) {
            data[back.*] = value;
        }

        back.* = back.* + 1;
        if (back.* >= DEQUE_MAX_SIZE) {
            back.* = 0;
        }
        count.* = count.* + 1;
        return true;
    }

    // deque_pop_front(data: []i32, front: *usize, back: *usize, count: *usize, value: *i32) -> bool
    // Remove element from front of deque
    fn deque_pop_front(data: []i32, front: *usize, back: *usize, count: *usize, value: *i32) -> bool {
        if (count.* == 0) {
            return false;
        }

        if (front.* < data.len) {
            value.* = data[front.*];
        }

        front.* = front.* + 1;
        if (front.* >= DEQUE_MAX_SIZE) {
            front.* = 0;
        }
        count.* = count.* - 1;
        return true;
    }

    // deque_pop_back(data: []i32, front: *usize, back: *usize, count: *usize, value: *i32) -> bool
    // Remove element from back of deque
    fn deque_pop_back(data: []i32, front: *usize, back: *usize, count: *usize, value: *i32) -> bool {
        if (count.* == 0) {
            return false;
        }

        if (back.* == 0) {
            back.* = DEQUE_MAX_SIZE - 1;
        } else {
            back.* = back.* - 1;
        }

        if (back.* < data.len) {
            value.* = data[back.*];
        }
        count.* = count.* - 1;
        return true;
    }

    // deque_peek_front(data: []i32, front: *usize, count: usize, value: *i32) -> bool
    // Look at element at front without removing
    fn deque_peek_front(data: []i32, front: *usize, count: usize, value: *i32) -> bool {
        if (count == 0) {
            return false;
        }
        if (front.* < data.len) {
            value.* = data[front.*];
        }
        return true;
    }

    // deque_peek_back(data: []i32, back: *usize, count: usize, value: *i32) -> bool
    // Look at element at back without removing
    fn deque_peek_back(data: []i32, back: *usize, count: usize, value: *i32) -> bool {
        if (count == 0) {
            return false;
        }
        var idx : usize = 0;
        if (back.* == 0) {
            idx = DEQUE_MAX_SIZE - 1;
        } else {
            idx = back.* - 1;
        }
        if (idx < data.len) {
            value.* = data[idx];
        }
        return true;
    }

    // deque_is_empty(count: usize) -> bool
    // Check if deque is empty
    fn deque_is_empty(count: usize) -> bool {
        return count == 0;
    }

    // deque_is_full(count: usize) -> bool
    // Check if deque is full
    fn deque_is_full(count: usize) -> bool {
        return count >= DEQUE_MAX_SIZE;
    }

    // deque_size(count: usize) -> usize
    // Get number of elements in deque
    fn deque_size(count: usize) -> usize {
        return count;
    }

    // deque_clear(data: []i32, front: *usize, back: *usize, count: *usize) -> void
    // Clear all elements from deque
    fn deque_clear(data: []i32, front: *usize, back: *usize, count: *usize) -> void {
        var i : usize = 0;
        while (i < DEQUE_MAX_SIZE and i < data.len) {
            data[i] = TRIT_ZERO;
            i = i + 1;
        }
        front.* = 0;
        back.* = 0;
        count.* = 0;
    }

    // =====================================================
    // 3. TDD - Tests
    // =========================================================================

    test deque_init_empty
        var data : [10]i32 = undefined;
        var front : usize = 99;
        var back : usize = 99;
        var count : usize = 99;
        deque_init(&data, &front, &back, &count);

        assert count == 0
        assert front == 0
        assert back == 0

    test deque_push_back_pop_front
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_POS);
        deque_push_back(&data, &front, &back, &count, TRIT_NEG);

        var value : i32 = 0;
        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_POS

        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_NEG

    test deque_push_front_pop_back
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_front(&data, &front, &back, &count, TRIT_POS);
        deque_push_front(&data, &front, &back, &count, TRIT_NEG);

        var value : i32 = 0;
        deque_pop_back(&data, &front, &back, &count, &value);
        assert value == TRIT_POS

        deque_pop_back(&data, &front, &back, &count, &value);
        assert value == TRIT_NEG

    test deque_peek_front
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_POS);

        var value : i32 = 0;
        deque_peek_front(&data, &front, count, &value);
        assert value == TRIT_POS
        assert count == 1  // Size unchanged

    test deque_peek_back
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_POS);
        deque_push_back(&data, &front, &back, &count, TRIT_NEG);

        var value : i32 = 0;
        deque_peek_back(&data, &back, count, &value);
        assert value == TRIT_NEG
        assert count == 2  // Size unchanged

    test deque_is_empty_full
        var data : [5]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        assert deque_is_empty(count)
        assert !deque_is_full(count)

        deque_push_back(&data, &front, &back, &count, TRIT_POS);
        assert !deque_is_empty(count)

    test deque_push_back_full
        var data : [5]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        var i : usize = 0;
        while (i < DEQUE_MAX_SIZE) {
            deque_push_back(&data, &front, &back, &count, TRIT_POS);
            i = i + 1;
        }

        assert deque_is_full(count)
        const success = deque_push_back(&data, &front, &back, &count, TRIT_NEG);
        assert !success

    test deque_clear
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_POS);
        deque_push_front(&data, &front, &back, &count, TRIT_NEG);
        deque_clear(&data, &front, &back, &count);

        assert deque_is_empty(count)

    // =====================================================
    // 4. TDD - Invariants
    // =========================================================================

    invariant deque_size_matches_operations
        // Size equals pushes minus pops
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        var i : usize = 0;
        while (i < 5) {
            deque_push_back(&data, &front, &back, &count, TRIT_POS);
            i = i + 1;
        }

        var value : i32 = 0;
        deque_pop_front(&data, &front, &back, &count, &value);

        assert deque_size(count) == 4

    invariant deque_pop_from_empty_fails
        // Pop from empty deque fails
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        var value : i32 = 0;
        const success1 = deque_pop_front(&data, &front, &back, &count, &value);
        const success2 = deque_pop_back(&data, &front, &back, &count, &value);

        assert !success1
        assert !success2

    invariant deque_fifo_order
        // Elements maintain FIFO order when pushed/popped from same ends
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_NEG);
        deque_push_back(&data, &front, &back, &count, TRIT_ZERO);
        deque_push_back(&data, &front, &back, &count, TRIT_POS);

        var value : i32 = 0;
        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_NEG

        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_ZERO

        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_POS

    invariant deque_lifo_order_front
        // Elements maintain LIFO order when pushed/popped from front
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_front(&data, &front, &back, &count, TRIT_NEG);
        deque_push_front(&data, &front, &back, &count, TRIT_ZERO);
        deque_push_front(&data, &front, &back, &count, TRIT_POS);

        var value : i32 = 0;
        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_POS

        deque_pop_front(&data, &front, &back, &count, &value);
        assert value == TRIT_ZERO

    invariant deque_peek_does_not_change_size
        // Peek operations don't change size
        var data : [10]i32 = undefined;
        var front : usize = 0;
        var back : usize = 0;
        var count : usize = 0;
        deque_init(&data, &front, &back, &count);

        deque_push_back(&data, &front, &back, &count, TRIT_POS);
        deque_push_front(&data, &front, &back, &count, TRIT_NEG);

        var value : i32 = 0;
        _ = deque_peek_front(&data, &front, count, &value);
        _ = deque_peek_back(&data, &back, count, &value);

        assert deque_size(count) == 2

    // =====================================================
    // 5. TDD - Benchmarks
    // =========================================================================

    bench deque_push_back_performance
        // Measure: cycles for 1000 push_back operations
        // Target: < 3000 cycles
        var data : [DEQUE_MAX_SIZE]i32 = undefined;
