// SPDX-License-Identifier: Apache-2.0
// ternary_add.t27 -- Balanced Ternary Addition Formal Spec
// Ring 043 -- Formal carry propagation invariants, closure, range formula
// phi^2 + 1/phi^2 = 3 | TRINITY

module ternary_add;

use base::types;

// ============================================================================
// 1. Full Adder for Balanced Ternary
// ============================================================================

// FullAdderResult: Result of trit addition with carry
pub struct FullAdderResult {
    sum : Trit,
    carry_out : Trit,
}

// trit_full_adder(a: Trit, b: Trit, c_in: Trit) -> FullAdderResult
// Full ternary adder with carry propagation
// Computes: sum = a + b + c_in (mod 3, mapped to {-1, 0, +1})
//          carry_out = -1 if a+b+c_in < -1, +1 if > +1, else 0
pub fn trit_full_adder(a: Trit, b: Trit, c_in: Trit) FullAdderResult {
    // Raw sum in [-3, +3]
    const raw: i8 = @intFromEnum(a) + @intFromEnum(b) + @intFromEnum(c_in);

    // Normalize to trit domain [-1, 0, +1] and compute carry
    if (raw > 1) {
        // raw = 2 or 3
        // raw = 2 -> sum = -1, carry = +1 (2 = -1 + 3*1)
        // raw = 3 -> sum = 0, carry = +1 (3 = 0 + 3*1)
        return FullAdderResult{
            .sum = if (raw == 2) .neg else .zero,
            .carry_out = .pos,
        };
    } else if (raw < -1) {
        // raw = -2 or -3
        // raw = -2 -> sum = +1, carry = -1 (-2 = +1 + 3*(-1))
        // raw = -3 -> sum = 0, carry = -1 (-3 = 0 + 3*(-1))
        return FullAdderResult{
            .sum = if (raw == -2) .pos else .zero,
            .carry_out = .neg,
        };
    } else {
        // raw = -1, 0, +1 -> no carry needed
        return FullAdderResult{
            .sum = @as(Trit, @enumFromInt(raw)),
            .carry_out = .zero,
        };
    }
}

// ============================================================================
// 2. Range and Capacity Functions
// ============================================================================

// max_value(k: u8) -> i64
// Maximum positive value representable with k trits
// Formula: (3^k - 1) / 2
pub fn max_value(k: u8) i64 {
    var pow3: i64 = 1;
    var i: u8 = 0;
    while (i < k) : (i += 1) {
        pow3 *= 3;
    }
    return (pow3 - 1) / 2;
}

// min_value(k: u8) -> i64
// Minimum negative value representable with k trits
// Formula: -(3^k - 1) / 2
pub fn min_value(k: u8) i64 {
    return -max_value(k);
}

// total_states(k: u8) -> i64
// Total number of states representable with k trits
// Formula: 3^k
pub fn total_states(k: u8) i64 {
    var result: i64 = 1;
    var i: u8 = 0;
    while (i < k) : (i += 1) {
        result *= 3;
    }
    return result;
}

// ============================================================================
// 3. Trit Multiplication Closure
// ============================================================================

// trit_mul_closed(a: Trit, b: Trit) -> Trit
// Trit multiplication is closed: {-1,0,+1} x {-1,0,+1} -> {-1,0,+1}
pub fn trit_mul_closed(a: Trit, b: Trit) Trit {
    return switch (a) {
        .neg => switch (b) {
            .neg => .pos,  // (-1) * (-1) = +1
            .zero => .zero,
            .pos => .neg,  // (-1) * (+1) = -1
        },
        .zero => .zero,  // 0 * x = 0
        .pos => b,  // (+1) * x = x
    };
}

// verify_trit_mul_closure() -> bool
// Verify that trit multiplication is closed
pub fn verify_trit_mul_closure() bool {
    const trits = [_]Trit{ .neg, .zero, .pos };
    for (trits) |a| {
        for (trits) |b| {
            const result = trit_mul_closed(a, b);
            // Result must be in {-1, 0, +1}
            const val = @intFromEnum(result);
            if (val < -1 or val > 1) {
                return false;
            }
        }
    }
    return true;
}

// ============================================================================
// 4. Carry Propagation Rules
// ============================================================================

// carry_sign(sum: i8) -> Trit
// Determine carry sign from raw sum
// Returns +1 if sum > 1, -1 if sum < -1, else 0
pub fn carry_sign(sum: i8) Trit {
    return if (sum > 1) .pos else if (sum < -1) .neg else .zero;
}

// normalize_trit(raw: i8) -> Trit
// Normalize raw sum to trit domain [-1, 0, +1]
// Uses modulo 3 arithmetic: raw mod 3 mapped to {-1, 0, +1}
pub fn normalize_trit(raw: i8) Trit {
    const mod3: i8 = @rem(raw, 3);
    return if (mod3 == 2) .neg else if (mod3 == -2) .pos else @as(Trit, @enumFromInt(mod3));
}

// ============================================================================
// 5. TDD -- Tests
// ============================================================================

test ternary_add_full_adder_pos_pos_zero
    // +1 + +1 + 0 = +2 -> sum = -1, carry = +1
    given result = trit_full_adder(.pos, .pos, .zero)
    then result.sum == .neg and result.carry_out == .pos

test ternary_add_full_adder_neg_neg_zero
    // -1 + -1 + 0 = -2 -> sum = +1, carry = -1
    given result = trit_full_adder(.neg, .neg, .zero)
    then result.sum == .pos and result.carry_out == .neg

test ternary_add_full_adder_pos_neg_zero
    // +1 + -1 + 0 = 0 -> sum = 0, carry = 0
    given result = trit_full_adder(.pos, .neg, .zero)
    then result.sum == .zero and result.carry_out == .zero

test ternary_add_full_adder_pos_pos_pos
    // +1 + +1 + +1 = +3 -> sum = 0, carry = +1
    given result = trit_full_adder(.pos, .pos, .pos)
    then result.sum == .zero and result.carry_out == .pos

test ternary_add_full_adder_neg_neg_neg
    // -1 + -1 + -1 = -3 -> sum = 0, carry = -1
    given result = trit_full_adder(.neg, .neg, .neg)
