invariant ternary_add_trit_mul_closure
    // Trit multiplication is closed: {-1,0,+1} x {-1,0,+1} -> {-1,0,+1}
    // Rationale: Fundamental algebraic property of balanced ternary
    assert verify_trit_mul_closure() == true

invariant ternary_add_trit_mul_commutative
    // trit_mul_closed(a, b) == trit_mul_closed(b, a)
    // Rationale: Multiplication is commutative in trit domain
    assert trit_mul_closed(a, b) == trit_mul_closed(b, a) for all Trit a, b

invariant ternary_add_range_formula
    // max_value(k) == (3^k - 1) / 2 for all k
    // Rationale: Balanced ternary range formula
    assert max_value(k) == (pow(3, k) - 1) / 2 for all k in u8 where k <= 27

invariant ternary_add_range_symmetric
    // max_value(k) == -min_value(k) for all k
    // Rationale: Balanced ternary is symmetric around zero
    assert max_value(k) == -min_value(k) for all k in u8 where k > 0

invariant ternary_add_total_states_power_of_three
    // total_states(k) == 3^k for all k
    // Rationale: Each trit has 3 states, k trits have 3^k combinations
    assert total_states(k) == pow(3, k) for all k in u8 where k <= 27

invariant ternary_add_full_adder_sum_in_range
    // trit_full_adder result sum is always in {-1, 0, +1}
    // Rationale: Full adder normalizes to trit domain
    assert trit_full_adder(a, b, c).sum in {-1, 0, +1} for all Trit a, b, c

invariant ternary_add_full_adder_carry_in_range
    // trit_full_adder carry_out is always in {-1, 0, +1}
    // Rationale: Carry is also a trit
    assert trit_full_adder(a, b, c).carry_out in {-1, 0, +1} for all Trit a, b, c

invariant ternary_add_carry_sign_matches_range
    // carry_sign(s) returns +1 if s > 1, -1 if s < -1, else 0
    // Rationale: Carry detection from raw sum
    assert carry_sign(s) == .pos implies s > 1
    assert carry_sign(s) == .neg implies s < -1
    assert carry_sign(s) == .zero implies -1 <= s <= 1

invariant ternary_add_normalize_trit_idempotent
    // normalize_trit(normalize_trit(x)) == normalize_trit(x)
    // Rationale: Normalizing twice gives same result
    assert normalize_trit(normalize_trit(x)) == normalize_trit(x) for all i8 x

invariant ternary_add_full_adder_zero_identity
    // trit_full_adder(a, 0, 0).sum == a for all a
    // Rationale: Zero is additive identity
    assert trit_full_adder(a, .zero, .zero).sum == a for all Trit a

invariant ternary_add_full_adder_commutative
    // trit_full_adder(a, b, c) == trit_full_adder(b, a, c)
    // Rationale: Addition is commutative
    assert trit_full_adder(a, b, c).sum == trit_full_adder(b, a, c).sum for all Trit a, b, c

