// SPDX-License-Identifier: Apache-2.0
// t27/specs/base/ternary_encoding.t27
// Ternary Encoding/Decoding Specification
// Ring 065 - Encoding schemes for ternary data representation
// Defines how binary data maps to ternary and vice versa
// phi^2 + 1/phi^2 = 3 | TRINITY

module TernaryEncoding {
    use base::types;

    // =====================================================
    // 1. Encoding Constants
    // =========================================================================

    // Trit values
    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // Encoding schemes
    const ENCODING_BALANCED : u8 = 0;   // Balanced ternary (-1, 0, 1)
    const ENCODING_UNIPOLAR : u8 = 1;   // Unipolar ternary (0, 1, 2)
    const ENCODING_BCT : u8 = 2;        // Binary Coded Ternary

    // Grouping sizes
    const BITS_PER_BYTE : usize = 8;
    const TRITS_PER_BYTE : usize = 6;    // 6 trits = 3^6 = 729 > 256
    const TRITS_PER_NYBBLE : usize = 3;   // 3 trits = 27 > 16

    // =====================================================
    // 2. Bit to Trit Conversion
    // =========================================================================

    // bit_to_trit_pair(bit: u8) -> [2]i32
    // Convert a single bit (0 or 1) to a pair of trits
    // 0 -> [0, 0], 1 -> [1, 0]
    fn bit_to_trit_pair(bit: u8) -> [2]i32 {
        if (bit == 0) {
            return [_]i32{TRIT_ZERO, TRIT_ZERO};
        }
        return [_]i32{TRIT_POS, TRIT_ZERO};
    }

    // bits_to_trits(bits: u8) -> [3]i32
    // Convert a nibble (4 bits) to 3 trits
    // Maps 0-15 to balanced ternary
    fn bits_to_trits(bits: u8) -> [3]i32 {
        var result : [3]i32 = [_]i32{TRIT_ZERO, TRIT_ZERO, TRIT_ZERO};
        var value = bits;
        var i : usize = 0;

        while (i < 3 and value > 0) {
            const rem = @rem(value, 3);
            if (rem == 2) {
                result[i] = TRIT_NEG;
                value = value / 3 + 1;
            } else {
                result[i] = @as(i32, @intCast(rem));
                value = value / 3;
            }
            i = i + 1;
        }

        return result;
    }

    // =====================================================
    // 3. Trit to Bit Conversion
    // =========================================================================

    // trits_to_bits(trits: [3]i32) -> u8
    // Convert 3 trits to a nibble (4 bits)
    // Assumes trits represent a valid value 0-15
    fn trits_to_bits(trits: [3]i32) -> u8 {
        var result : i32 = 0;
        var power : i32 = 1;
        var i : usize = 0;

        while (i < 3) {
            var trit_val = trits[i];
            // Convert negative to positive for unipolar representation
            if (trit_val == TRIT_NEG) {
                trit_val = 2;
            }
            result = result + trit_val * power;
            power = power * 3;
            i = i + 1;
        }

        return @as(u8, @intCast(result));
    }

    // =====================================================
    // 4. Byte to Trit Array Conversion
    // =========================================================================

    // byte_to_trits(byte: u8, trits: []i32, len: usize) -> usize
    // Convert a byte to trits
    // Returns number of trits used
    fn byte_to_trits(byte: u8, trits: []i32, len: usize) -> usize {
        // Convert byte (0-255) to balanced ternary
        var value : i32 = @as(i32, @intCast(byte));
        var i : usize = 0;

        while (i < len and value != 0) {
            const rem = @rem(value, 3);

            if (rem == 2) {
                trits[i] = TRIT_NEG;
                value = value / 3 + 1;
            } else if (rem == -2) {
                trits[i] = TRIT_POS;
                value = value / 3 - 1;
            } else {
                trits[i] = rem;
                value = value / 3;
            }

            i = i + 1;
        }

        // Pad remaining trits with zero
        while (i < len) {
            trits[i] = TRIT_ZERO;
            i = i + 1;
        }

        return len;
    }

    // trits_to_byte(trits: []i32, len: usize) -> u8
    // Convert trits to a byte
    // Assumes trits represent a valid value 0-255
    fn trits_to_byte(trits: []i32, len: usize) -> u8 {
        var result : i32 = 0;
        var power : i32 = 1;
        var i : usize = 0;

        while (i < len) {
            var trit_val = trits[i];
            // Convert balanced to unipolar
            if (trit_val == TRIT_NEG) {
                trit_val = 2;
            }
            result = result + trit_val * power;
            power = power * 3;
            i = i + 1;
        }

        return @as(u8, @intCast(result));
    }

    // =====================================================
    // 5. Balanced to Unipolar Conversion
    // =========================================================================

    // balanced_to_unipolar(trit: i32) -> i32
    // Convert balanced ternary trit to unipolar
    // -1 -> 0, 0 -> 1, 1 -> 2
    fn balanced_to_unipolar(trit: i32) -> i32 {
        return trit + 1;
    }

    // unipolar_to_balanced(trit: i32) -> i32
    // Convert unipolar trit to balanced ternary
    // 0 -> -1, 1 -> 0, 2 -> 1
    fn unipolar_to_balanced(trit: i32) -> i32 {
        return trit - 1;
    }

    // =====================================================
    // 6. String Encoding
    // =========================================================================

    // char_to_trits(c: u8, trits: []i32, len: usize) -> usize
    // Convert ASCII character to trits
    fn char_to_trits(c: u8, trits: []i32, len: usize) -> usize {
        return byte_to_trits(c, trits, len);
    }

    // trits_to_char(trits: []i32, len: usize) -> u8
    // Convert trits to ASCII character
    fn trits_to_char(trits: []i32, len: usize) -> u8 {
        return trits_to_byte(trits, len);
    }

    // =====================================================
    // 7. Validation
    // =========================================================================

    // is_valid_trit(t: i32) -> bool
    // Check if a value is a valid trit
    fn is_valid_trit(t: i32) -> bool {
        return t >= TRIT_NEG and t <= TRIT_POS;
    }

    // is_valid_unipolar_trit(t: i32) -> bool
    // Check if a value is a valid unipolar trit (0, 1, 2)
    fn is_valid_unipolar_trit(t: i32) -> bool {
        return t >= 0 and t <= 2;
    }

    // validate_trits(trits: []i32, len: usize) -> bool
    // Validate all trits in an array
    fn validate_trits(trits: []i32, len: usize) -> bool {
        var i : usize = 0;
        while (i < len) {
            if (!is_valid_trit(trits[i])) {
                return false;
            }
            i = i + 1;
        }
        return true;
    }

    // =====================================================
    // 8. Encoding Metadata
    // =========================================================================

    struct EncodingInfo {
        encoding_type : u8,
        trits_used : usize,
        byte_value : u8,
        is_valid : bool,
    }

    // get_encoding_info(trits: []i32, len: usize) -> EncodingInfo
    // Get information about a trit encoding
    fn get_encoding_info(trits: []i32, len: usize) -> EncodingInfo {
        var info : EncodingInfo = undefined;
        info.encoding_type = ENCODING_BALANCED;
        info.trits_used = len;
        info.is_valid = validate_trits(trits, len);

        if (info.is_valid) {
            info.byte_value = trits_to_byte(trits, len);
        } else {
            info.byte_value = 0;
        }

        return info;
    }

    // =====================================================
    // 9. TDD - Tests
    // =========================================================================

    test bit_to_trit_pair_zero
        const result = bit_to_trit_pair(0);
        assert result[0] == TRIT_ZERO
        assert result[1] == TRIT_ZERO

    test bit_to_trit_pair_one
        const result = bit_to_trit_pair(1);
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_ZERO

    test bits_to_trits_zero
        const result = bits_to_trits(0);
        assert result[0] == TRIT_ZERO
        assert result[1] == TRIT_ZERO
        assert result[2] == TRIT_ZERO

    test bits_to_trits_max_nibble
        const result = bits_to_trits(15);
        const decoded = trits_to_bits(result);
        assert decoded == 15

    test trits_to_bits_roundtrip
        var i : u8 = 0;
        while (i < 16) {
            const trits = bits_to_trits(i);
            const decoded = trits_to_bits(trits);
            assert decoded == i
            i = i + 1;
        }

    test byte_to_trits_roundtrip
        var i : u8 = 0;
        var trits : [10]i32 = undefined;
        while (i < 10) {
            byte_to_trits(i, &trits, 10);
            const decoded = trits_to_byte(&trits, 10);
            assert decoded == i
            i = i + 1;
        }

    test balanced_unipolar_conversion
        assert balanced_to_unipolar(TRIT_NEG) == 0
        assert balanced_to_unipolar(TRIT_ZERO) == 1
        assert balanced_to_unipolar(TRIT_POS) == 2

        assert unipolar_to_balanced(0) == TRIT_NEG
        assert unipolar_to_balanced(1) == TRIT_ZERO
        assert unipolar_to_balanced(2) == TRIT_POS

    test is_valid_trit_check
        assert is_valid_trit(TRIT_NEG) == true
        assert is_valid_trit(TRIT_ZERO) == true
        assert is_valid_trit(TRIT_POS) == true
        assert is_valid_trit(2) == false
        assert is_valid_trit(-2) == false

    test is_valid_unipolar_trit_check
        assert is_valid_unipolar_trit(0) == true
        assert is_valid_unipolar_trit(1) == true
        assert is_valid_unipolar_trit(2) == true
        assert is_valid_unipolar_trit(3) == false
        assert is_valid_unipolar_trit(-1) == false

    test char_encoding_roundtrip
        var test_chars : [5]u8 = [_]u8{'A', '0', ' ', '\n', 127};
        var trits : [10]i32 = undefined;
        var i : usize = 0;
        while (i < 5) {
            char_to_trits(test_chars[i], &trits, 10);
            const decoded = trits_to_char(&trits, 10);
            assert decoded == test_chars[i]
            i = i + 1;
        }

    // =====================================================
    // 10. TDD - Invariants
    // =========================================================================

    invariant balanced_unipolar_roundtrip
        // Converting balanced -> unipolar -> balanced should be identity
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            const uni = balanced_to_unipolar(vals[i]);
            const balanced = unipolar_to_balanced(uni);
            assert balanced == vals[i]
            i = i + 1;
        }

    invariant byte_trits_roundtrip
        // byte -> trits -> byte should be identity for all bytes
        var trits : [10]i32 = undefined;
        var byte_val : u8 = 0;
        while (true) {
            byte_to_trits(byte_val, &trits, 10);
            const decoded = trits_to_byte(&trits, 10);
            assert decoded == byte_val

            if (byte_val == 255) { break; }
            byte_val = byte_val + 1;
        }

    invariant bits_trits_roundtrip
        // bits -> trits -> bits should be identity for 0-15
        var i : u8 = 0;
        while (i < 16) {
            const trits = bits_to_trits(i);
            const decoded = trits_to_bits(trits);
            assert decoded == i
            i = i + 1;
        }

    invariant encoding_info_validity
        // Encoding info should reflect validity correctly
        var valid_trits : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var invalid_trits : [3]i32 = [_]i32{2, 0, 1};

        const valid_info = get_encoding_info(&valid_trits, 3);
        const invalid_info = get_encoding_info(&invalid_trits, 3);

        assert valid_info.is_valid == true
        assert invalid_info.is_valid == false

    invariant trits_used_in_encoding_info
        // Encoding info should report correct trits used
        var trits : [5]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_ZERO, TRIT_POS};
        const info = get_encoding_info(&trits, 5);
        assert info.trits_used == 5

    // =====================================================
    // 11. TDD - Benchmarks
    // =========================================================================

    bench byte_to_trits_performance
        // Measure: cycles to convert 100 bytes to trits
        // Target: < 3000 cycles
        var trits : [10]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..100) |i| {
            byte_to_trits(@as(u8, @intCast(i % 256)), &trits, 10);
        }

    bench trits_to_byte_performance
        // Measure: cycles to convert 100 trit arrays to bytes
        // Target: < 2000 cycles
        var trits : [10]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS};
        @setEvalBranchQuota(10000);
        var result : u8 = 0;
        for (0..100) |_| {
            result = trits_to_byte(&trits, 10);
        }
        _ = result;

    bench balanced_unipolar_performance
        // Measure: cycles to convert 1000 trits between representations
        // Target: < 500 cycles
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        @setEvalBranchQuota(10000);
        var result : i32 = 0;
        var idx : usize = 0;
        for (0..1000) |_| {
            const uni = balanced_to_unipolar(vals[idx % 3]);
            result = unipolar_to_balanced(uni);
            idx = idx + 1;
        }
        _ = result;
}

