// t27/specs/pins/ir.t27
// Pins Intermediate Representation (IR)
// Models FPGA pin assignments, I/O standards, clock constraints
// phi^2 + 1/phi^2 = 3 | TRINITY

module PinsIR {
    use base::types;
    use base::ops;

    struct PinLocation {
        package_pin : &str,
        port_name : &str,
        bank : u8,
    }

    struct IoStandard {
        name : &str,
        voltage : &str,
        drive_strength_ma : u8,
        slew_fast : bool,
    }

    struct SignalReference {
        port_name : &str,
        direction : &str,
        width : usize,
        index : i32,
    }

    struct Binding {
        location : PinLocation,
        standard : IoStandard,
        signal : SignalReference,
        is_clock : bool,
        pullup : bool,
        pulldown : bool,
    }

    struct ClockDef {
        port_name : &str,
        name : &str,
        period_ns : u32,
        waveform_high_ns : u32,
        add : bool,
    }

    struct Design {
        name : &str,
        fpga_part : &str,
        bindings : [256]Binding,
        clocks : [16]ClockDef,
        binding_count : usize,
        clock_count : usize,
    }

    const LVCMOS33 : IoStandard = IoStandard{
        .name = "LVCMOS33",
        .voltage = "3.3",
        .drive_strength_ma = 12,
        .slew_fast = false,
    };

    fn make_input_signal(port: &str, width: usize) -> SignalReference {
        return SignalReference{
            .port_name = port,
            .direction = "input",
            .width = width,
            .index = -1,
        };
    }

    fn make_output_signal(port: &str, width: usize) -> SignalReference {
        return SignalReference{
            .port_name = port,
            .direction = "output",
            .width = width,
            .index = -1,
        };
    }

    fn make_indexed_signal(port: &str, idx: i32) -> SignalReference {
        return SignalReference{
            .port_name = port,
            .direction = "output",
            .width = 1,
            .index = idx,
        };
    }

    fn make_location(pin: &str, port: &str, bank: u8) -> PinLocation {
        return PinLocation{
            .package_pin = pin,
            .port_name = port,
            .bank = bank,
        };
    }

    fn make_binding(
        loc: PinLocation,
        sig: SignalReference,
        is_clk: bool,
    ) -> Binding {
        return Binding{
            .location = loc,
            .standard = LVCMOS33,
            .signal = sig,
            .is_clock = is_clk,
            .pullup = false,
            .pulldown = false,
        };
    }

    fn make_clock(port: &str, name: &str, period: u32, high: u32) -> ClockDef {
        return ClockDef{
            .port_name = port,
            .name = name,
            .period_ns = period,
            .waveform_high_ns = high,
            .add = true,
        };
    }

    fn empty_design(name: &str, part: &str) -> Design {
        return Design{
            .name = name,
            .fpga_part = part,
            .bindings = [Binding{
                .location = PinLocation{.package_pin = "", .port_name = "", .bank = 0},
                .standard = LVCMOS33,
                .signal = SignalReference{.port_name = "", .direction = "", .width = 0, .index = -1},
                .is_clock = false,
                .pullup = false,
                .pulldown = false,
            }; 256],
            .clocks = [ClockDef{
                .port_name = "",
                .name = "",
                .period_ns = 0,
                .waveform_high_ns = 0,
                .add = false,
            }; 16],
            .binding_count = 0,
            .clock_count = 0,
        };
    }

    fn add_binding(d: Design, b: Binding) -> Design {
        var out = d;
        if (out.binding_count < 256) {
            out.bindings[out.binding_count] = b;
            out.binding_count = out.binding_count + 1;
        }
        return out;
    }

    fn add_clock(d: Design, c: ClockDef) -> Design {
        var out = d;
        if (out.clock_count < 16) {
            out.clocks[out.clock_count] = c;
            out.clock_count = out.clock_count + 1;
        }
        return out;
    }

    fn has_pin_conflict(d: Design) -> bool {
        var i : usize = 0;
        while (i < d.binding_count) {
            var j : usize = i + 1;
            while (j < d.binding_count) {
                if (d.bindings[i].location.package_pin == d.bindings[j].location.package_pin) {
                    if (d.bindings[i].location.package_pin != "") {
                        return true;
                    }
                }
                j = j + 1;
            }
            i = i + 1;
        }
        return false;
    }

    fn has_port_conflict(d: Design) -> bool {
        var i : usize = 0;
        while (i < d.binding_count) {
            var j : usize = i + 1;
            while (j < d.binding_count) {
                if (d.bindings[i].signal.port_name == d.bindings[j].signal.port_name) {
                    if (d.bindings[i].signal.index == d.bindings[j].signal.index) {
                        if (d.bindings[i].signal.port_name != "") {
                            return true;
                        }
                    }
                }
                j = j + 1;
            }
            i = i + 1;
        }
        return false;
    }

    fn clock_bound(d: Design, port: &str) -> bool {
        var i : usize = 0;
        while (i < d.clock_count) {
            if (d.clocks[i].port_name == port) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn all_clock_ports_bound(d: Design) -> bool {
        var i : usize = 0;
        while (i < d.binding_count) {
            if (d.bindings[i].is_clock) {
                if (!clock_bound(d, d.bindings[i].signal.port_name)) {
                    return false;
                }
            }
            i = i + 1;
        }
        return true;
    }

    fn binding_count(d: Design) -> usize {
        return d.binding_count;
    }

    fn clock_count(d: Design) -> usize {
        return d.clock_count;
    }

    fn signal_direction(sig: SignalReference) -> &str {
        return sig.direction;
    }

    fn is_indexed(sig: SignalReference) -> bool {
        return sig.index >= 0;
    }

    fn format_port_name(sig: SignalReference) -> &str {
        if (sig.index >= 0) {
            return sig.port_name;
        }
        return sig.port_name;
    }

    test make_input_signal_direction
        given sig = make_input_signal("clk", 1)
        then sig.direction == "input" and sig.port_name == "clk" and sig.width == 1

    test make_output_signal_direction
        given sig = make_output_signal("led", 8)
        then sig.direction == "output" and sig.port_name == "led" and sig.width == 8

    test make_indexed_signal
        given sig = make_indexed_signal("led", 3)
        then sig.index == 3 and sig.direction == "output"

    test make_location_fields
        given loc = make_location("E3", "clk", 0)
        then loc.package_pin == "E3" and loc.port_name == "clk" and loc.bank == 0

    test make_binding_fields
        given loc = make_location("E3", "clk", 0)
        and   sig = make_input_signal("clk", 1)
        and   b = make_binding(loc, sig, true)
        then b.is_clock == true and b.standard.name == "LVCMOS33" and b.pullup == false

    test make_clock_fields
        given clk = make_clock("clk", "sys_clk", 83, 41)
        then clk.port_name == "clk" and clk.name == "sys_clk" and clk.period_ns == 83 and clk.waveform_high_ns == 41

    test empty_design_zero_bindings
        given d = empty_design("test", "xc7a100t")
        then d.binding_count == 0 and d.clock_count == 0 and d.name == "test"

    test add_binding_increments_count
        given d = empty_design("test", "xc7a100t")
        and   loc = make_location("E3", "clk", 0)
        and   sig = make_input_signal("clk", 1)
        and   b = make_binding(loc, sig, true)
        and   d2 = add_binding(d, b)
        then d2.binding_count == 1

    test add_clock_increments_count
        given d = empty_design("test", "xc7a100t")
        and   clk = make_clock("clk", "sys_clk", 83, 41)
        and   d2 = add_clock(d, clk)
        then d2.clock_count == 1

    test no_conflict_single_pin
        given d = empty_design("test", "xc7a100t")
        and   loc = make_location("E3", "clk", 0)
        and   sig = make_input_signal("clk", 1)
        and   b = make_binding(loc, sig, true)
        and   d2 = add_binding(d, b)
        then has_pin_conflict(d2) == false

    test conflict_detected_duplicate_pin
        given d = empty_design("test", "xc7a100t")
        and   loc1 = make_location("E3", "clk", 0)
        and   sig1 = make_input_signal("clk", 1)
        and   b1 = make_binding(loc1, sig1, true)
        and   d2 = add_binding(d, b1)
        and   loc2 = make_location("E3", "rst_n", 0)
        and   sig2 = make_input_signal("rst_n", 1)
        and   b2 = make_binding(loc2, sig2, false)
        and   d3 = add_binding(d2, b2)
        then has_pin_conflict(d3) == true

    test no_port_conflict_different_indices
        given d = empty_design("test", "xc7a100t")
        and   loc1 = make_location("H17", "led", 1)
        and   sig1 = make_indexed_signal("led", 0)
        and   b1 = make_binding(loc1, sig1, false)
        and   d2 = add_binding(d, b1)
        and   loc2 = make_location("K15", "led", 1)
        and   sig2 = make_indexed_signal("led", 1)
        and   b2 = make_binding(loc2, sig2, false)
        and   d3 = add_binding(d2, b2)
        then has_port_conflict(d3) == false

    test all_clocks_bound_true
        given d = empty_design("test", "xc7a100t")
        and   loc = make_location("E3", "clk", 0)
        and   sig = make_input_signal("clk", 1)
        and   b = make_binding(loc, sig, true)
        and   d2 = add_binding(d, b)
        and   clk = make_clock("clk", "sys_clk", 83, 41)
        and   d3 = add_clock(d2, clk)
        then all_clock_ports_bound(d3) == true

    test all_clocks_bound_false_missing_clock
        given d = empty_design("test", "xc7a100t")
        and   loc = make_location("E3", "clk", 0)
        and   sig = make_input_signal("clk", 1)
        and   b = make_binding(loc, sig, true)
        and   d2 = add_binding(d, b)
        then all_clock_ports_bound(d2) == false

    test lvcmos33_standard
        given std = LVCMOS33
        then std.name == "LVCMOS33" and std.voltage == "3.3"

    test is_indexed_true
        given sig = make_indexed_signal("led", 0)
        then is_indexed(sig) == true

    test is_indexed_false
        given sig = make_input_signal("clk", 1)
        then is_indexed(sig) == false

    test signal_direction_input
        given sig = make_input_signal("rx", 1)
        then signal_direction(sig) == "input"

    test signal_direction_output
        given sig = make_output_signal("tx", 1)
        then signal_direction(sig) == "output"

    invariant lvcmos33_name
        given std = LVCMOS33
        assert std.name == "LVCMOS33"

    invariant empty_design_has_no_conflicts
        given d = empty_design("test", "xc7a100t")
        assert has_pin_conflict(d) == false and has_port_conflict(d) == false

    invariant empty_design_no_clocks_bound_vacuously
        given d = empty_design("test", "xc7a100t")
        assert all_clock_ports_bound(d) == true

    invariant binding_count_non_negative
        given d = empty_design("test", "xc7a100t")
        assert binding_count(d) >= 0

    invariant clock_count_non_negative
        given d = empty_design("test", "xc7a100t")
        assert clock_count(d) >= 0

    bench make_binding_latency
        measure: nanoseconds to make_binding(make_location("E3", "clk", 0), make_input_signal("clk", 1), true)
        target: < 500ns

    bench has_pin_conflict_latency
        measure: nanoseconds to has_pin_conflict(empty_design("test", "xc7a100t"))
        target: < 1000ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/math/radix_economy.t27
// Radix Economy Formal Spec -- Information-Theoretic Basis for Base-3 Computing
// E(b) = ln(b)/b, maximized at b = e ~= 2.71828
// E(3)/E(e) >= 99.5%, E(3)/E(2) = 1.054 (5.4% advantage)

module RadixEconomy {
    use Constants;

    // ===========================================================================
    // 1. Radix Economy Constants
    // =========================================================================================

    // E(b) = ln(b) / b -- information per digit
    // E(2) = ln(2)/2 ~= 0.34657 -- binary radix economy
    const E_BASE2 : f64 = 0.34657359027997264; // ln(2)/2

    // E(3) = ln(3)/3 ~= 0.36620 -- ternary radix economy
    const E_BASE3 : f64 = 0.3662040962227032; // ln(3)/3

    // E(e) = 1/e ~= 0.36788 -- optimal radix economy (theoretical maximum)
    const E_OPTIMAL : f64 = 0.36787944117144233; // 1/e

    // log2(3) ~= 1.58496 -- bits per trit (information density)
    const LOG2_3 : f64 = 1.584962500721156;

    // log3(2) ~= 0.63093 -- trits per bit (inverse density)
    const LOG3_2 : f64 = 0.6309297535714574;

    // ===========================================================================
    // 2. Radix Economy Functions
    // =========================================================================================

    // Compute radix economy for base b
    fn radix_economy(b: f64) -> f64 {
        return ln(b) / b;
    }

    // Compute efficiency relative to optimal base e
    fn efficiency_ratio(b: f64) -> f64 {
        return radix_economy(b) / E_OPTIMAL;
    }

    // Compare two bases: ratio of their radix economies
    fn base_advantage(b1: f64, b2: f64) -> f64 {
        return radix_economy(b1) / radix_economy(b2);
    }

    // Information density: bits per digit
    fn info_density_bits(b: f64) -> f64 {
        return log2(b);
    }

    // Ternary range: maximum value for n trits (balanced: -(3^n-1)/2 to (3^n-1)/2)
    fn ternary_range(n: i64) -> i64 {
        return (pow(3.0, n as f64) - 1.0) as i64 / 2;
    }

    // Binary range: maximum value for n bits
    fn binary_range(n: i64) -> i64 {
        return (pow(2.0, n as f64) - 1.0) as i64;
    }

    // ===========================================================================
    // 3. Helper Functions (logarithms)
    // =========================================================================================

    // Natural logarithm
    fn ln(x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0 / 0.0; // NaN
        }
        if x == 1.0 {
            return 0.0;
        }
        // Series: ln(x) = 2 * sum_{k=0..inf} (1/(2k+1)) * ((x-1)/(x+1))^(2k+1)
        let t = (x - 1.0) / (x + 1.0);
        let t2 = t * t;
        let t3 = t2 * t;
        let t5 = t3 * t2;
        let t7 = t5 * t2;
        let t9 = t7 * t2;
        return 2.0 * (t + t3 / 3.0 + t5 / 5.0 + t7 / 7.0 + t9 / 9.0);
    }

    // Base-2 logarithm: log2(x) = ln(x) / ln(2)
    fn log2(x: f64) -> f64 {
        return ln(x) / ln(2.0);
    }

    // Power function (for range calculations)
    fn pow(x: f64, n: f64) -> f64 {
        if x < 0.0 and n != floor(n) {
            return 0.0 / 0.0;
        }
        if x == 0.0 {
            if n > 0.0 { return 0.0; }
            if n == 0.0 { return 1.0; }
            return 1.0 / 0.0;
        }
        if n == 0.0 { return 1.0; }

        let negative = n < 0.0;
        let exp = if negative { -n } else { n };
        let is_integer = exp == floor(exp);

        if is_integer {
            let exp_int = exp as i64;
            let mut result = 1.0;
            let mut base = x;
            let mut e = exp_int;

            while e > 0 {
                if e % 2 == 1 {
                    result = result * base;
                }
                base = base * base;
                e = e / 2;
            }

            if negative { result = 1.0 / result; }
            return result;
        }

        // Fractional: use log/exp
        let ln_x = ln(x);
        let mut result = 1.0;
        let mut term = 1.0;
        for i in 1..=12 {
            term = term * exp * ln_x / (i as f64);
            result = result + term;
        }

        if negative { result = 1.0 / result; }
        return result;
    }

    // Natural exponential: e^x (simplified)
    fn exp(x: f64) -> f64 {
        if x == 0.0 { return 1.0; }

        let mut result = 1.0;
        let mut term = 1.0;

        for i in 1..=12 {
            term = term * x / (i as f64);
            result = result + term;
        }

        return result;
    }

    // Floor function
    fn floor(x: f64) -> f64 {
        let xi = x as i64;
        if x >= 0.0 || x == xi as f64 {
            return xi as f64;
        }
        return (xi - 1) as f64;
    }

    // ===========================================================================
    // 4. TDD-Inside-Spec: Tests for Radix Economy
    // =========================================================================================

    test e_base3_near_optimal
        given e3 = E_BASE3
        and   e_optimal = E_OPTIMAL
        when  ratio = e3 / e_optimal
        then  ratio >= 0.995
        and   ratio <= 1.0

    test e_base3_beats_base2
        given e3 = E_BASE3
        and   e2 = E_BASE2
        when  ratio = e3 / e2
        and   advantage = (e3 - e2) / e2
        then  e3 > e2
        and   ratio >= 1.05
        and   advantage >= 0.05

    test log2_3_accuracy
        given log2_3 = LOG2_3
        when  lower = 1.58496
        and   upper = 1.58497
        then  log2_3 >= lower and log2_3 <= upper

    test log3_2_accuracy
        given log3_2 = LOG3_2
        when  reciprocal = 1.0 / LOG2_3
        then  abs(log3_2 - reciprocal) < 1e-6

    test ternary_vs_binary_range_27trit
        given trit_range = ternary_range(27)
        and   bit_range_42 = binary_range(42)
        and   bit_range_43 = binary_range(43)
        when  trit_range
        then  trit_range > bit_range_42
        and   trit_range <= bit_range_43

    test ternary_vs_binary_range_18trit
        given trit_range = ternary_range(18)
        and   bit_range_28 = binary_range(28)
        and   bit_range_29 = binary_range(29)
        when  trit_range
        then  trit_range > bit_range_28
        and   trit_range <= bit_range_29

    test radix_economy_function_correctness
        given e2_computed = radix_economy(2.0)
        and   e3_computed = radix_economy(3.0)
        and   e_e_computed = radix_economy(2.718281828459045)
        when  err_e2 = abs(e2_computed - E_BASE2)
        and   err_e3 = abs(e3_computed - E_BASE3)
        and   err_ee = abs(e_e_computed - E_OPTIMAL)
        then  err_e2 < 1e-6 and err_e3 < 1e-6 and err_ee < 1e-6

    test efficiency_ratio_base3
        given eff3 = efficiency_ratio(3.0)
        when  eff3
        then  eff3 >= 0.995 and eff3 <= 1.0

    test base_advantage_3_vs_2
        given advantage = base_advantage(3.0, 2.0)
        when  advantage
        then  advantage >= 1.054

    test info_density_trit
        given density = info_density_bits(3.0)
        when  density
        then  abs(density - LOG2_3) < 1e-6

    test ln_function_accuracy
        given ln_e = ln(E)
        when  ln_e
        then  abs(ln_e - 1.0) < 1e-6

    test ln_function_ln2
        given ln_2 = ln(2.0)
        when  ln_2
        then  abs(ln_2 - 0.693147) < 1e-5

    test ln_function_ln3
        given ln_3 = ln(3.0)
        when  ln_3
        then  abs(ln_3 - 1.098612) < 1e-5

    test log2_function_accuracy
        given log2_2 = log2(2.0)
        and   log2_4 = log2(4.0)
        and   log2_8 = log2(8.0)
        when  results
        then  abs(log2_2 - 1.0) < 1e-6
        and   abs(log2_4 - 2.0) < 1e-6
        and   abs(log2_8 - 3.0) < 1e-6

    // ===========================================================================
    // 5. Formal Invariants -- Mathematical Truths
    // =========================================================================================

    invariant base3_995_percent_optimal
        assert E_BASE3 / E_OPTIMAL >= 0.995
        // Rationale: E(3) >= 99.5% of E(e), proven by calculus: d/db(ln(b)/b)=0 => b=e

    invariant base3_superior_to_base2
        assert E_BASE3 > E_BASE2
        // Rationale: ln(3)/3 > ln(2)/2 by direct computation

    invariant base3_54_percent_advantage
        assert (E_BASE3 - E_BASE2) / E_BASE2 >= 0.054
        // Rationale: (0.3662 - 0.3466) / 0.3466 = 0.054 = 5.4%

    invariant log2_3_in_range
        assert LOG2_3 >= 1.58496 and LOG2_3 <= 1.58497
        // Rationale: log2(3) ~= 1.584962500721156

    invariant trit_info_density
        assert LOG2_3 > 1.5 and LOG2_3 < 2.0
        // Rationale: A trit contains more information than a bit (1.58 > 1), less than 2 bits

    invariant radix_economy_monotonic_increase_to_e
        assert for b in [2, 3], E(b) <= E(b+1) when b < e
        // Rationale: E(b) = ln(b)/b increases for b < e, decreases for b > e

    invariant optimal_base_is_e
        assert E_OPTIMAL = 1/e
        // Rationale: Maximizing ln(b)/b gives b = e by calculus

    invariant ternary_range_balanced
        assert ternary_range(n) = (3^n - 1) / 2 for all positive integer n
        // Rationale: Balanced ternary represents integers from -(3^n-1)/2 to (3^n-1)/2

    invariant binary_range_standard
        assert binary_range(n) = 2^n - 1 for all positive integer n
        // Rationale: Unsigned binary represents integers from 0 to 2^n - 1

    invariant range_equivalence_27trit_43bit
        assert ternary_range(27) <= binary_range(43)
        and   ternary_range(27) > binary_range(42)
        // Rationale: (3^27-1)/2 ~= 3.8e12, 2^42 ~= 4.4e12, 2^43 ~= 8.8e12

    invariant range_equivalence_18trit_29bit
        assert ternary_range(18) <= binary_range(29)
        and   ternary_range(18) > binary_range(28)
        // Rationale: 3^18 ~= 3.9e8, 2^28 ~= 2.7e8, 2^29 ~= 5.4e8

    invariant log_reciprocal_identity
        assert LOG3_2 * LOG2_3 = 1.0 within 1e-6
        // Rationale: log_a(b) * log_b(a) = 1 for any valid bases

    // ===========================================================================
    // 6. Benchmarks -- Performance Targets
    // =========================================================================================

    bench radix_economy_computation
        measure: cycles to compute radix_economy(3.0)
        target: < 100 cycles

    bench log2_computation
        measure: cycles to compute log2(3.0)
        target: < 200 cycles

    bench ternary_range_27
        measure: cycles to compute ternary_range(27)
        target: < 500 cycles

    bench base_advantage_3_vs_2
        measure: cycles to compute base_advantage(3.0, 2.0)
        target: < 150 cycles
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/numeric/gf4.t27
// GoldenFloat4 -- 4-bit phi-structured floating point
// NUMERIC-STANDARD-001 -- Agent 2 (P1)

module GF4 {
    // Import base format family
    use numeric::goldenfloat_family;
    use numeric::phi_ratio;

    // =================================================================
    // 1. Format Definition
    // =========================================================================

    // GF4 bit layout: [S|E|MM]
    //   S: 1 bit  (sign)
    //   E: 1 bit  (exponent)
    //   M: 2 bits (mantissa)

    const BITS : u8 = 4;
    const SIGN_BITS : u8 = 1;
    const EXP_BITS : u8 = 1;
    const MANT_BITS : u8 = 2;

    // Bias for exponent (0-biased for GF4)
    const EXP_BIAS : u8 = 0;

    // phi-ratio: exp/mant = 1/2 = 0.5 (phi_distance = 0.118)
    const PHI_DISTANCE : f64 = 0.1180339887498949;

    // =================================================================
    // 2. GoldenFloat4 Type
    // =========================================================================

    struct GF4 {
        raw : u4,  // 4-bit raw value
    }

    // =================================================================
    // 3. Encoding/Decoding
    // =========================================================================

    // Encode f32 to GF4
    fn encode(value: f32) -> GF4 {
        // Special cases
        if (value == 0.0) {
            return GF4{ raw = 0b0000 };
        }
        if (value < 0.0) {
            const pos = encode(-value).raw;
            return GF4{ raw = pos | 0b1000 };  // Set sign bit
        }

        // For GF4, quantize to available values
        // Available positive values (mant * exp_scale):
        // mant=0.00, exp=1.0 -> 0.00
        // mant=0.25, exp=1.0 -> 0.25
        // mant=0.50, exp=1.0 -> 0.50
        // mant=0.75, exp=1.0 -> 0.75
        // mant=0.00, exp=2.0 -> 0.00
        // mant=0.25, exp=2.0 -> 0.50
        // mant=0.50, exp=2.0 -> 1.00
        // mant=0.75, exp=2.0 -> 1.50

        // Unique positive non-zero values: 0.25, 0.5, 0.75, 1.0, 1.5

        if (value <= 0.375) {
            // 0.25
            return GF4{ raw = 0b0001 };
        } else if (value <= 0.625) {
            // 0.5
            return GF4{ raw = 0b0010 };
        } else if (value <= 0.875) {
            // 0.75
            return GF4{ raw = 0b0011 };
        } else if (value <= 1.25) {
            // 1.0
            return GF4{ raw = 0b0101 };
        } else {
            // 1.5 (max)
            return GF4{ raw = 0b0111 };
        }
    }

    // Decode GF4 to f32
    fn decode(gf: GF4) -> f32 {
        const sign_bit = (gf.raw & 0b1000) != 0;
        const exp_bit = (gf.raw & 0b0100) != 0;
        const mant_bits = gf.raw & 0b0011;

        // Zero
        if (gf.raw == 0) {
            return 0.0;
        }

        // Decode mantissa (2 bits -> values 0, 0.25, 0.5, 0.75)
        const mant = (mant_bits as f32) / 4.0;

        // Decode exponent (1 bit -> 1.0 or 2.0)
        const exp_scale = if (exp_bit) { 2.0 } else { 1.0 };

        const value = mant * exp_scale;

        if (sign_bit) {
            return -value;
        }
        return value;
    }

    // =================================================================
    // 4. Format Properties
    // =========================================================================

    fn max_value() -> f32 {
        // Max: mant=0.75, exp=2.0 -> 1.5
        return 1.5;
    }

    fn min_positive() -> f32 {
        // Min positive: mant=0.25, exp=1.0 -> 0.25
        return 0.25;
    }

    fn epsilon() -> f32 {
        // Smallest representable difference at 1.0
        return 0.25;
    }

    // =================================================================
    // 5. Validation
    // =========================================================================

    fn validate_format() -> bool {
        // Check that we match the goldenfloat_family definition
        const fmt = goldenfloat_family::get_format_by_name("GF4");
        return (fmt != null) &&
               (fmt.?.bits == BITS) &&
               (fmt.?.exp_bits == EXP_BITS) &&
               (fmt.?.mant_bits == MANT_BITS);
    }

    // =================================================================
    // 6. Use Cases
    // =========================================================================

    // GF4 is optimal for:
    // - Extreme compression (87.5% smaller than FP32)
    // - Binary/ternary classification
    // - Attention masks
    // - Activation sparsity indicators

    // Memory: 4 bits = 0.5 bytes (8x FP32 in same space)
    const MEMORY_RATIO_VS_FP32 : f32 = 4.0 / 32.0;  // 0.125

    // =======================================================================================================
    // TDD-Inside-Spec: Tests and Invariants for GF4
    // =======================================================================================================

    test gf4_decode_zero
        given gf = GF4{ raw = 0b0000 }
        when value = decode(gf)
        then value == 0.0

    test gf4_decode_positive_max
        given gf = GF4{ raw = 0b0111 }
        when value = decode(gf)
        then value == 1.5

    test gf4_decode_negative
        given gf = GF4{ raw = 0b1001 }
        when value = decode(gf)
        then value < 0.0

    test gf4_encode_zero_roundtrip
        given original = 0.0
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then decoded == original

    test gf4_encode_0_25
        given original = 0.25
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 0.25) < 0.01

    test gf4_encode_0_5
        given original = 0.5
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 0.5) < 0.01

    test gf4_encode_0_75
        given original = 0.75
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 0.75) < 0.01

    test gf4_encode_1_0
        given original = 1.0
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 1.0) < 0.01

    test gf4_encode_1_5
        given original = 1.5
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 1.5) < 0.01

    test gf4_encode_negative_values
        given original = -0.5
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then decoded < 0.0 and abs(decoded - (-0.5)) < 0.01

    test gf4_encode_clamps_to_max
        given original = 10.0
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then decoded <= 1.5

    test gf4_encode_quantization_small
        given original = 0.3
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then abs(decoded - 0.25) < 0.01

    test gf4_max_value_is_1_5
        given max_val = max_value()
        then max_val == 1.5

    test gf4_min_positive_is_0_25
        given min_pos = min_positive()
        then min_pos == 0.25

    test gf4_bits_sum_correct
        given total = SIGN_BITS + EXP_BITS + MANT_BITS
        then total == BITS

    test gf4_exp_mant_ratio_matches_phi_split
        given ratio = (EXP_BITS as f64) / (MANT_BITS as f64)
        and   expected = 0.5
        then abs(ratio - expected) < 0.01

    test gf4_memory_ratio_vs_fp32
        given ratio = MEMORY_RATIO_VS_FP32
        then ratio == 0.125

    test gf4_validate_format_success
        given valid = validate_format()
        then valid == true

    invariant gf4_bits_constant
        assert BITS == 4

    invariant gf4_sign_bits_is_one
        assert SIGN_BITS == 1

    invariant gf4_exp_bits_is_one
        assert EXP_BITS == 1

    invariant gf4_mant_bits_is_two
        assert MANT_BITS == 2

    invariant gf4_max_value_positive
        assert max_value() > 0.0

    invariant gf4_min_positive_greater_than_zero
        assert min_positive() > 0.0

    invariant gf4_epsilon_positive
        assert epsilon() > 0.0

    invariant gf4_max_ge_min_positive
        assert max_value() >= min_positive()

    invariant gf4_phi_distance_within_tolerance
        assert PHI_DISTANCE < 0.12

    invariant gf4_encode_decode_roundtrip
        given encoded = encode(x) for x in {0.25, 0.5, 0.75, 1.0, 1.5}
        when decoded = decode(encoded)
        then abs(decoded - x) < 0.01

    invariant gf4_encode_zero_returns_zero
        assert encode(0.0).raw == 0b0000

    invariant gf4_encode_positive_no_sign_bit
        given result = encode(1.0)
        when has_sign = (result.raw & 0b1000) != 0
        then has_sign == false

    invariant gf4_encode_negative_has_sign_bit
        given result = encode(-1.0)
        when has_sign = (result.raw & 0b1000) != 0
        then has_sign == true

    bench gf4_encode_latency
        measure: nanoseconds to encode(1.0)
        target: < 100ns

    bench gf4_decode_latency
        measure: nanoseconds to decode(GF4{raw = 0b0101})
        target: < 50ns
}

// SPDX-License-Identifier: CC0-1.0
// SANDBOX-012: HTTPS Enforcement

/**
 * Module: sandbox.https_enforce
 *
 * Enforces HTTPS for all API requests.
 * - Production: redirect HTTP to HTTPS (301 permanent redirect)
 * - Local: allow HTTP for development
 * - Uses X-Forwarded-Proto header when behind proxy
 *
 * This prevents mixed content and ensures all traffic is encrypted.
 */

module sandbox.https_enforce;

// ─────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────

const HTTPS_REDIRECT_STATUS : u16 = 301;
const HTTPS_SCHEME : &[u8; 5] = b"https";
const HTTP_SCHEME : &[u8; 4] = b"http";
const LOCAL_HOSTNAMES : [&[u8; 9]; 3] = [b"localhost", b"127.0.0.1", b"[::1]"];

// ─────────────────────────────────────────────
// Request Context
// ─────────────────────────────────────────────

pub struct RequestContext {
    forwarded_proto: Option<&[u8]>,
    host: &[u8],
    is_local: bool,
}

// ─────────────────────────────────────────────
// Core Logic
// ─────────────────────────────────────────────

/**
 * Determine if a request should be redirected to HTTPS.
 *
 * Redirect rules:
 * 1. Never redirect in local mode (localhost/127.0.0.1/::1)
 * 2. Never redirect if X-Forwarded-Proto is "https"
 * 3. Always redirect if X-Forwarded-Proto is "http" or missing
 *
 * @param ctx - Request context containing headers and local flag
 * @return true if redirect to HTTPS is required
 */
fn should_redirect(ctx: &RequestContext) -> bool {
    // Local mode: never redirect
    if ctx.is_local {
        return false;
    }

    match ctx.forwarded_proto {
        Some(proto) => {
            // If explicitly set to https, no redirect needed
            proto == HTTPS_SCHEME
        },
        None => true,  // No header = assume HTTP, redirect
    }
}

/**
 * Build HTTPS redirect URL from original HTTP URL.
 *
 * @param original_url - Original HTTP URL
 * @return HTTPS URL
 */
fn redirect_url(original_url: &[u8]) -> Vec<u8> {
    let mut result = Vec::with_capacity(original_url.len() + 1);
    let scheme_end = if original_url.len() > 7 && &original_url[..7] == b"http://" {
        7
    } else if original_url.len() > 8 && &original_url[..8] == b"https://" {
        8  // Already HTTPS, return as-is
    } else {
        0  // No scheme prefix
    };

    if scheme_end > 0 {
        result.extend_from_slice(HTTPS_SCHEME);
        result.extend_from_slice(b"://");
        result.extend_from_slice(&original_url[scheme_end..]);
    } else {
        result.extend_from_slice(original_url);
    }
    result
}

/**
 * Check if a hostname indicates a local development environment.
 *
 * @param host - Hostname to check
 * @return true if hostname is local
 */
fn is_local_hostname(host: &[u8]) -> bool {
    LOCAL_HOSTNAMES.iter().any(|local| *local == host)
}

// ─────────────────────────────────────────────
// Interface
// ─────────────────────────────────────────────

/**
 * HTTPS enforcement middleware interface.
 */
pub trait HttpsEnforcer {
    /**
     * Check if request should redirect and build redirect URL.
     *
     * @param ctx - Request context
     * @return None if no redirect, Some(https_url) if redirect needed
     */
    fn enforce(&self, ctx: &RequestContext) -> Option<Vec<u8>>;
}

// ─────────────────────────────────────────────
// TDD Tests
// ─────────────────────────────────────────────

.test {
    use sandbox.https_enforce;

    fn make_ctx(forwarded_proto: Option<&[u8]>, host: &[u8]) -> RequestContext {
        RequestContext {
            forwarded_proto,
            host,
            is_local: is_local_hostname(host),
        }
    }

    // Test: HTTPS requests are NOT redirected
    test "https_not_redirected" {
        input: {
            ctx: make_ctx(Some(HTTPS_SCHEME), b"api.t27.dev"),
        };
        expected: false;
        description: "Requests with X-Forwarded-Proto: https should not be redirected";
    }

    // Test: HTTP requests in production ARE redirected
    test "http_redirected_in_prod" {
        input: {
            ctx: make_ctx(Some(HTTP_SCHEME), b"api.t27.dev"),
        };
        expected: true;
        description: "Requests with X-Forwarded-Proto: http should be redirected to HTTPS";
    }

    // Test: Missing proto header triggers redirect
    test "no_proto_header_redirected" {
        input: {
            ctx: make_ctx(None, b"api.t27.dev"),
        };
        expected: true;
        description: "Requests without X-Forwarded-Proto should be redirected";
    }

    // Test: Local mode never redirects
    test "local_mode_never_redirects" {
        input: {
            ctx: make_ctx(Some(HTTP_SCHEME), b"localhost"),
        };
        expected: false;
        description: "Requests to localhost should never be redirected";
    }

    // Test: Redirect URL construction is correct
    test "redirect_url_correct" {
        input: {
            original_url: b"http://api.t27.dev/health",
        };
        expected: b"https://api.t27.dev/health";
        description: "HTTP URL should be converted to HTTPS URL";
    }

    // Test: HTTPS URL remains unchanged
    test "https_url_unchanged" {
        input: {
            original_url: b"https://api.t27.dev/health",
        };
        expected: b"https://api.t27.dev/health";
        description: "Already HTTPS URL should remain unchanged";
    }

    // Test: 127.0.0.1 is considered local
    test "127_0_0_1_is_local" {
        input: {
            ctx: make_ctx(Some(HTTP_SCHEME), b"127.0.0.1"),
        };
        expected: false;
        description: "Requests to 127.0.0.1 should never be redirected";
    }

    // Test: IPv6 localhost is considered local
    test "ipv6_localhost_is_local" {
        input: {
            ctx: make_ctx(Some(HTTP_SCHEME), b"[::1]"),
        };
        expected: false;
        description: "Requests to [::1] should never be redirected";
    }

    // Test: Port is preserved in redirect
    test "redirect_preserves_port" {
        input: {
            original_url: b"http://api.t27.dev:8080/health",
        };
        expected: b"https://api.t27.dev:8080/health";
        description: "Port number should be preserved in HTTPS redirect";
    }

    // Test: Query string is preserved in redirect
    test "redirect_preserves_query" {
        input: {
            original_url: b"http://api.t27.dev/health?debug=true",
        };
        expected: b"https://api.t27.dev/health?debug=true";
        description: "Query string should be preserved in HTTPS redirect";
    }
}

