// SPDX-License-Identifier: Apache-2.0
; int4.t27 — Int4 Signed 4-bit Integer Quantization
; Range: -8 to 7
; Used for ultra-low precision quantization in ML
; φ² + 1/φ² = 3 | TRINITY

module triformat-int4;

// ============================================================================
// Constants
// ============================================================================

pub const BITS : u8 = 4;
pub const MIN : i8 = -8;
pub const MAX : i8 = 7;
pub const RANGE : u8 = 16;  // 2^4

pub const MASK : u8 = 0x0F;  // Lower 4 bits mask

// ============================================================================
// Types
// ============================================================================

pub const Int4 = i8;  // Stored as i8, but only lower 4 bits used

// ============================================================================
// Conversion Functions
// ============================================================================

// int4_from_i8(value: i8) -> Int4
// Convert i8 to Int4 with saturation
// Values < -8 clamp to -8, values > 7 clamp to 7
pub fn int4_from_i8(value: i8) Int4 {
    if (value < MIN) {
        return MIN;
    } else if (value > MAX) {
        return MAX;
    }
    return value;
}

// int4_from_i16(value: i16) -> Int4
// Convert i16 to Int4 with saturation
pub fn int4_from_i16(value: i16) Int4 {
    if (value < @as(i16, MIN)) {
        return MIN;
    } else if (value > @as(i16, MAX)) {
        return MAX;
    }
    return @as(i8, @intCast(value));
}

// int4_from_i32(value: i32) -> Int4
// Convert i32 to Int4 with saturation
pub fn int4_from_i32(value: i32) Int4 {
    if (value < @as(i32, MIN)) {
        return MIN;
    } else if (value > @as(i32, MAX)) {
        return MAX;
    }
    return @as(i8, @intCast(value));
}

// int4_from_f32(value: f32) -> Int4
// Convert f32 to Int4 with rounding and saturation
// Round to nearest, ties to even
pub fn int4_from_f32(value: f32) Int4 {
    if (std.math.isNan(value)) {
        return 0;
    }
    if (value > @as(f32, @floatFromInt(MAX)) + 0.5) {
        return MAX;
    }
    if (value < @as(f32, @floatFromInt(MIN)) - 0.5) {
        return MIN;
    }
    // Round to nearest
    const rounded = @as(i32, @intFromFloat(@round(value)));
    return int4_from_i32(rounded);
}

// int4_to_i8(value: Int4) -> i8
// Convert Int4 to i8 (no-op, just returns value)
pub fn int4_to_i8(value: Int4) i8 {
    return value;
}

// int4_to_i16(value: Int4) -> i16
// Convert Int4 to i16 (sign extension)
pub fn int4_to_i16(value: Int4) i16 {
    // Sign extend from 4 bits to 16 bits
    return @as(i16, value);
}

// int4_to_i32(value: Int4) -> i32
// Convert Int4 to i32 (sign extension)
pub fn int4_to_i32(value: Int4) i32 {
    return @as(i32, value);
}

// int4_to_f32(value: Int4) -> f32
// Convert Int4 to f32
pub fn int4_to_f32(value: Int4) f32 {
    return @as(f32, @floatFromInt(value));
}

// int4_to_f64(value: Int4) -> f64
// Convert Int4 to f64
pub fn int4_to_f64(value: Int4) f64 {
    return @as(f64, @floatFromInt(value));
}

// ============================================================================
// Arithmetic Operations
// ============================================================================

// int4_add(a: Int4, b: Int4) -> Int4
// Add two Int4 values with saturation
pub fn int4_add(a: Int4, b: Int4) Int4 {
    const result = a + b;
    if (result > MAX) {
        return MAX;
    } else if (result < MIN) {
        return MIN;
    }
    return result;
}

// int4_sub(a: Int4, b: Int4) -> Int4
// Subtract two Int4 values with saturation
pub fn int4_sub(a: Int4, b: Int4) Int4 {
    const result = a - b;
    if (result > MAX) {
        return MAX;
    } else if (result < MIN) {
        return MIN;
    }
    return result;
}

// int4_mul(a: Int4, b: Int4) -> Int4
// Multiply two Int4 values with saturation
pub fn int4_mul(a: Int4, b: Int4) Int4 {
    const result = a * b;
    if (result > MAX) {
        return MAX;
    } else if (result < MIN) {
        return MIN;
    }
    return result;
}

// int4_div(a: Int4, b: Int4) -> Int4
// Divide two Int4 values with saturation
// Division by zero returns MAX or MIN based on sign of numerator
pub fn int4_div(a: Int4, b: Int4) Int4 {
    if (b == 0) {
        return if (a >= 0) MAX else MIN;
    }
    const result = a / b;
    if (result > MAX) {
        return MAX;
    } else if (result < MIN) {
        return MIN;
    }
    return result;
}

// int4_abs(value: Int4) -> Int4
// Absolute value of Int4 with saturation
pub fn int4_abs(value: Int4) Int4 {
    if (value == MIN) {
        return MAX;  // -8 -> 7 (saturated)
    }
    return if (value < 0) -value else value;
}

// int4_neg(value: Int4) -> Int4
// Negate Int4 (with saturation for -MIN)
pub fn int4_neg(value: Int4) Int4 {
    if (value == MIN) {
        return MAX;  // -(-8) = 7 (saturated)
    }
    return -value;
}

// ============================================================================
// Comparison Functions
// ============================================================================

// int4_is_equal(a: Int4, b: Int4) -> bool
pub fn int4_is_equal(a: Int4, b: Int4) bool {
    return a == b;
}

// int4_is_greater(a: Int4, b: Int4) -> bool
pub fn int4_is_greater(a: Int4, b: Int4) bool {
    return a > b;
}

// int4_is_less(a: Int4, b: Int4) -> bool
pub fn int4_is_less(a: Int4, b: Int4) bool {
    return a < b;
}

// int4_min(a: Int4, b: Int4) -> Int4
pub fn int4_min(a: Int4, b: Int4) Int4 {
    return if (a < b) a else b;
}

// int4_max(a: Int4, b: Int4) -> Int4
pub fn int4_max(a: Int4, b: Int4) Int4 {
    return if (a > b) a else b;
}

// int4_clamp(value: Int4, min: Int4, max: Int4) -> Int4
pub fn int4_clamp(value: Int4, min: Int4, max: Int4) Int4 {
    if (value < min) {
        return min;
    } else if (value > max) {
        return max;
    }
    return value;
}

// ============================================================================
// Utility Functions
// ============================================================================

// int4_clamp_to_range(value: Int4) -> Int4
// Clamp value to Int4 range [-8, 7]
pub fn int4_clamp_to_range(value: Int4) Int4 {
    return int4_clamp(value, MIN, MAX);
}

// int4_is_in_range(value: i8) -> bool
// Check if value is in Int4 range
pub fn int4_is_in_range(value: i8) bool {
    return value >= MIN and value <= MAX;
}

// int4_lerp(a: Int4, b: Int4, t: f32) -> Int4
// Linear interpolation between a and b
pub fn int4_lerp(a: Int4, b: Int4, t: f32) Int4 {
    const fa = @as(f32, @floatFromInt(a));
    const fb = @as(f32, @floatFromInt(b));
    const result = fa + (fb - fa) * t;
    return int4_from_f32(result);
}

// int4_sq(value: Int4) -> Int4
// Square value with saturation
pub fn int4_sq(value: Int4) Int4 {
    return int4_mul(value, value);
}

// int4_abs_diff(a: Int4, b: Int4) -> Int4
// Absolute difference between two Int4 values
pub fn int4_abs_diff(a: Int4, b: Int4) Int4 {
    const diff = a - b;
    return int4_abs(diff);
}

