// SPDX-License-Identifier: Apache-2.0
// t27/specs/numeric/gf256.t27
// GoldenFloat256 0 256-bit 1-structured floating point
// NUMERIC-STANDARD-001 2 Agent 11 (P1)

module GF256 {
    // Import base format family
    use numeric::goldenfloat_family;
    use numeric::phi_ratio;

    // GF256 bit layout: [S(1) E(97) M(158)]
    //   S: 1 bit  (sign)
    //   E: 97 bits (exponent)
    //   M: 158 bits (mantissa)

    const BITS : u8 = 256;
    const SIGN_BITS : u8 = 1;
    const EXP_BITS : u8 = 97;
    const MANT_BITS : u8 = 158;

    // Bias for exponent (2^(97-1) - 1 = 0x7FFFFFFFFFFFFFFF)
    const EXP_BIAS_LO : u64 = 0xFFFFFFFFFFFFFFFF;
    const EXP_BIAS_HI : u64 = 0x7F;

    // phi-ratio: exp/mant = 97/158 ≈ 0.614 (phi_distance = 0.004)
    const PHI_DISTANCE : f64 = 0.00412087369321891;

    struct GF256 {
        // 256-bit value (4 x u64)
        raw_0 : u64,  // bits 0-63 (mantissa low)
        raw_1 : u64,  // bits 64-127 (mantissa high + exp low)
        raw_2 : u64,  // bits 128-191 (exp mid + mant high)
        raw_3 : u64,  // bits 192-255 (sign + exp high)
    }

    // Encode f64 to GF256
    fn encode(value: f64) -> GF256 {
        if (value == 0.0) {
            return GF256{ raw_0 = 0, raw_1 = 0, raw_2 = 0, raw_3 = 0 };
        }

        const sign = if (value < 0.0) { 1u64 } else { 0u64 };
        const abs_val = if (value < 0.0) { -value } else { value };

        // Extract exponent (unbiased)
        const exp_unbiased = floor_log2(abs_val) as i128;
        let exp_biased_lo = ((exp_unbiased + 158886469278522817) & 0xFFFFFFFFFFFFFFFF) as u64;
        let exp_biased_hi = ((exp_unbiased >> 64) + 127) as u64;

        // Clamp exponent
        if (exp_biased_hi > 0x7F) {
            exp_biased_hi = 0x7F;
            exp_biased_lo = 0xFFFFFFFFFFFFFFFF;
        }

        // Extract mantissa (158 bits, split across 3 u64 words)
        const normalized = abs_val / pow(2.0, exp_unbiased as f64);
        const frac = normalized - 1.0;
        const max_mant = (1u128 << MANT_BITS) - 1;
        const mant = (frac * (max_mant + 1) as f64) as u128;
        const clamped_mant = if (mant > max_mant) { max_mant } else { mant };

        // Pack mantissa
        const raw_0 = (clamped_mant & 0xFFFFFFFFFFFFFFFF) as u64;
        const raw_1 = ((clamped_mant >> 64) & 0x3FFFFFFFFFFFFFFF) as u64;

        // Pack exponent (97 bits: 31 in raw_1, 64 in raw_2, 2 in raw_3)
        const exp_m1 = (exp_biased_lo << 33) as u64;
        const exp_m2 = (exp_biased_lo >> 31) | ((exp_biased_hi & 0x1) << 33);

        // Pack sign (bit 255)
        const raw_3 = (sign << 63) | ((exp_biased_hi >> 1) & 0x7FFFFFFFFFFFFFFF);

        return GF256{
            raw_0 = raw_0,
            raw_1 = raw_1 | exp_m1,
            raw_2 = exp_m2,
            raw_3 = raw_3,
        };
    }

    // Decode GF256 to f64
    fn decode(gf: GF256) -> f64 {
        const sign = (gf.raw_3 >> 63) as u8;

        // Extract exponent (97 bits)
        const exp_lo_part = gf.raw_1 >> 33;
        const exp_mid_part = (gf.raw_2 & 0x1FFFFFFFFFFFFFFF) as u64;
        const exp_hi_part = (gf.raw_3 & 0x3FFFFFFFFFFFFFFF) as u64;
        const exp_biased_lo = exp_lo_part | (exp_mid_part << 31);
        const exp_biased_hi = exp_hi_part >> 62;

        const exp_biased_128 = ((exp_biased_hi as u128) << 64) | exp_biased_lo as u128;

        // Extract mantissa (158 bits)
        const mant_lo = gf.raw_0;
        const mant_mid = gf.raw_1 & 0x1FFFFFFFFFFFFFFF;
        const mant = ((mant_mid as u128) << 64) | mant_lo as u128;

        // Zero
        if (exp_biased_128 == 0 && mant == 0) {
            return 0.0;
        }

        // Exponent
        const exp_bias_128 = ((EXP_BIAS_HI as u128) << 64) | EXP_BIAS_LO as u128;
        const exp_unbiased = if (exp_biased_128 == 0) {
            -(exp_bias_128 as i128) + 1
        } else {
            (exp_biased_128 as i128) - exp_bias_128 as i128
        };

        // Mantissa
        const max_mant = (1u128 << MANT_BITS) - 1;
        const mant_normalized = if (exp_biased_128 == 0) {
            (mant as f64) / (max_mant + 1) as f64
        } else {
            1.0 + (mant as f64) / (max_mant + 1) as f64
        };

        const value = mant_normalized * pow(2.0, exp_unbiased as f64);

        if (sign != 0) {
            return -value;
        }
        return value;
    }

    // Format Properties
    fn max_value() -> f64 {
        const max_mant = (1u128 << MANT_BITS) - 1;
        const mant_max = 1.0 + (max_mant as f64) / (max_mant + 1) as f64;
        const exp_max = ((1i128 << EXP_BITS) - 1) as f64 - (EXP_BIAS_HI as f64 * 4294967296.0 + EXP_BIAS_LO as f64);
        return mant_max * pow(2.0, exp_max);
    }

    fn min_positive() -> f64 {
        const max_mant = (1u128 << MANT_BITS) - 1;
        const mant_min = 1.0 / (max_mant + 1) as f64;
        const exp_min = -((EXP_BIAS_HI as f64 * 4294967296.0 + EXP_BIAS_LO as f64)) + 1.0;
        return mant_min * pow(2.0, exp_min);
    }

    fn epsilon() -> f64 {
        const max_mant = (1u128 << MANT_BITS) - 1;
        return 1.0 / (max_mant + 1) as f64;
    }

    // Validation
    fn validate_format() -> bool {
        const fmt = goldenfloat_family::get_format_by_name("GF256");
        return (fmt != null) &&
               (fmt.?.bits == BITS) &&
               (fmt.?.exp_bits == EXP_BITS) &&
               (fmt.?.mant_bits == MANT_BITS);
    }

    // Use Cases
    // GF256 is optimal for:
    // - Maximum precision computational chemistry
    // - String theory simulations
    // - Exascale climate modeling
    // - Arbitrary-precision arithmetic bridge

    // Memory: 256 bits = 32 bytes (8x FP32)
    const MEMORY_RATIO_VS_FP32 : f32 = 8.0;

    // Helper Functions
    fn floor_log2(x: f64) -> i128 {
        if (x <= 0.0) { return -170141183460469231731687303715884105728; }
        let exp : i128 = 0;
        while (x >= 2.0) {
            x = x / 2.0;
            exp = exp + 1;
        }
        while (x < 1.0) {
            x = x * 2.0;
            exp = exp - 1;
        }
        return exp;
    }

    fn pow(base: f64, exp: f64) -> f64 {
        if (base <= 0.0 || exp == 0.0) {
            if (exp == 0.0) {
                return 1.0;
            }
            if (base == 0.0 && exp > 0.0) {
                return 0.0;
            }
            return 0.0 / 0.0;
        }

        const is_integer = exp == floor(exp);

        if (is_integer) {
            let exp_int = exp as i32;
            let result = 1.0;
            let base_acc = base;
            let e = exp_int;

            if (e < 0) {
                e = -e;
                base_acc = 1.0 / base_acc;
            }

            while (e > 0) {
                if (e % 2 == 1) {
                    result = result * base_acc;
                }
                base_acc = base_acc * base_acc;
                e = e / 2;
            }

            return result;
        }

        const ln_val = ln_approx(base);
        return exp_approx(exp * ln_val);
    }

    fn ln_approx(x: f64) -> f64 {
        if (x <= 0.0) {
            return 0.0 / 0.0;
        }
        if (x == 1.0) {
            return 0.0;
        }

        const t = (x - 1.0) / (x + 1.0);
        const t2 = t * t;
        const t3 = t2 * t;
        const t5 = t3 * t2;

        return 2.0 * (t + t3 / 3.0 + t5 / 5.0);
    }

    fn exp_approx(x: f64) -> f64 {
        if (x == 0.0) {
            return 1.0;
        }

        let result = 1.0;
        let term = 1.0;
        let exp_x = x;

        for (i in 1..=15) {
            term = term * exp_x / (i as f64);
            result = result + term;
        }

        return result;
    }

    fn floor(x: f64) -> f64 {
        let xi = x as i128;
        if (x >= 0.0 || x == xi as f64) {
            return xi as f64;
        }
        return (xi - 1) as f64;
    }

    // TDD-Inside-Spec: Tests and Invariants for GF256

    test gf256_decode_zero
        given gf = GF256{ raw_0 = 0, raw_1 = 0, raw_2 = 0, raw_3 = 0 }
        when value = decode(gf)
        then value == 0.0

    test gf256_encode_zero_roundtrip
        given original = 0.0
        and   encoded = encode(original)
        and   decoded = decode(encoded)
        then decoded == original

    test gf256_bits_sum_correct
        given total = SIGN_BITS + EXP_BITS + MANT_BITS
        then total == BITS

    test gf256_max_value_positive
        given max_val = max_value()
        then max_val > 0.0

    test gf256_min_positive_greater_than_zero
        given min_pos = min_positive()
        then min_pos > 0.0

    test gf256_epsilon_positive
        given eps = epsilon()
        then eps > 0.0

    test gf256_phi_distance_good
        given phi_dist = PHI_DISTANCE
        then phi_dist < 0.01

    test gf256_memory_ratio_vs_fp32
        given ratio = MEMORY_RATIO_VS_FP32
        then abs(ratio - 8.0) < 0.01

    test gf256_validate_format_success
        given valid = validate_format()
        then valid == true

    invariant gf256_bits_constant
        assert BITS == 256

    invariant gf256_sign_bits_is_one
        assert SIGN_BITS == 1

    invariant gf256_exp_bits_is_97
        assert EXP_BITS == 97

    invariant gf256_mant_bits_is_158
        assert MANT_BITS == 158

    invariant gf256_max_ge_min_positive
        assert max_value() >= min_positive()

    invariant gf256_phi_distance_below_threshold
        assert PHI_DISTANCE < 0.01

    invariant gf256_exp_mant_ratio_close_to_phi
        assert abs((EXP_BITS as f64) / (MANT_BITS as f64) - 0.618) < 0.01

    invariant gf256_has_max_precision
        // GF256 provides extreme precision suitable for quantum computing
        assert MANT_BITS > 100

    bench gf256_encode_latency
        measure: nanoseconds to encode(1.0)
        target: < 1000ns

    bench gf256_decode_latency
        measure: nanoseconds to decode(GF256{raw_0 = 0, raw_1 = 0, raw_2 = 0, raw_3 = 0})
        target: < 800ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/partition.t27
// T27 Multi-FPGA Partition Specification
// Automatically partitions HIR modules across multiple FPGAs
// Estimates inter-FPGA bandwidth and latency
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Partition {

    // === FPGA node ===

    pub struct FpgaNode {
        name : &str,
        device : &str,
        luts : u32,
        ffs : u32,
        bram18 : u32,
        dsp48 : u32,
        io_pins : u32,
    }

    fn fpga_node(name: &str, device: &str, luts: u32, ffs: u32, bram18: u32, dsp48: u32, io: u32) -> FpgaNode {
        return FpgaNode{
            .name = name,
            .device = device,
            .luts = luts,
            .ffs = ffs,
            .bram18 = bram18,
            .dsp48 = dsp48,
            .io_pins = io,
        };
    }

    fn arty_a7_node(name: &str) -> FpgaNode {
        return fpga_node(name, "xc7a100t", 63400, 126800, 135, 240, 300);
    }

    // === Inter-FPGA link ===

    pub struct InterFpgaLink {
        fpga_a : u32,
        fpga_b : u32,
        width : u32,
        protocol : i8,
        max_mbps : u32,
    }

    fn lvds_link(a: u32, b: u32, width: u32) -> InterFpgaLink {
        return InterFpgaLink{
            .fpga_a = a,
            .fpga_b = b,
            .width = width,
            .protocol = 0,
            .max_mbps = 1000,
        };
    }

    fn serdes_link(a: u32, b: u32) -> InterFpgaLink {
        return InterFpgaLink{
            .fpga_a = a,
            .fpga_b = b,
            .width = 4,
            .protocol = 1,
            .max_mbps = 6250,
        };
    }

    fn link_bandwidth_mbps(link: InterFpgaLink) -> u32 {
        return link.width * link.max_mbps;
    }

    // === Partition assignment ===

    pub struct PartitionAssign {
        module_name : &str,
        fpga_idx : u32,
        luts : u32,
        ffs : u32,
        bram18 : u32,
        dsp48 : u32,
    }

    // NB: the parameter is `mod_name`, not `module`. `module` is the keyword
    // that opens a declaration, and a parameter carrying that name aborts the
    // body parse -- silently, taking every declaration after it, tests
    // included, out of the emitted module.
    fn assignment(mod_name: &str, fpga: u32, luts: u32, ffs: u32, bram: u32, dsp: u32) -> PartitionAssign {
        return PartitionAssign{
            .module_name = mod_name,
            .fpga_idx = fpga,
            .luts = luts,
            .ffs = ffs,
            .bram18 = bram,
            .dsp48 = dsp,
        };
    }

    // === Partition result ===

    pub struct PartitionResult {
        num_fpgas : u32,
        num_assignments : u32,
        num_links : u32,
        total_bandwidth_mbps : u32,
        balanced : bool,
        errors : u32,
    }

    fn partition_ok(fpgas: u32, assigns: u32, links: u32, bw: u32) -> PartitionResult {
        return PartitionResult{
            .num_fpgas = fpgas,
            .num_assignments = assigns,
            .num_links = links,
            .total_bandwidth_mbps = bw,
            .balanced = true,
            .errors = 0,
        };
    }

    fn partition_fail(errors: u32) -> PartitionResult {
        return PartitionResult{
            .num_fpgas = 0,
            .num_assignments = 0,
            .num_links = 0,
            .total_bandwidth_mbps = 0,
            .balanced = false,
            .errors = errors,
        };
    }

    fn passed(r: PartitionResult) -> bool {
        return r.errors == 0;
    }

    // === Query ===

    // Read-only over the array, so the parameter is const: `[InterFpgaLink]`
    // emits a mutable slice, which no expression a test can write will coerce
    // to, and the test below could not be called at all.
    fn total_link_bandwidth(links: []const InterFpgaLink, count: u32) -> u32 {
        var total : u32 = 0;
        var i : u32 = 0;
        while i < count {
            total = total + link_bandwidth_mbps(links[i]);
            i = i + 1;
        }
        return total;
    }

    fn fpga_util(fpga: FpgaNode, used_luts: u32) -> u32 {
        if fpga.luts == 0 {
            return 0;
        }
        return used_luts * 100 / fpga.luts;
    }

    fn fpga_remaining(fpga: FpgaNode, used_luts: u32) -> u32 {
        if used_luts > fpga.luts {
            return 0;
        }
        return fpga.luts - used_luts;
    }

    // === Validation ===

    fn validate_node(n: FpgaNode) -> u32 {
        var errors : u32 = 0;
        if n.name == "" {
            errors = errors + 1;
        }
        if n.luts == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test fpga_node_creation
        given n = arty_a7_node("fpga0")
        then n.name == "fpga0"
        and n.device == "xc7a100t"
        and n.luts == 63400

    test lvds_link_creation
        given l = lvds_link(0, 1, 8)
        then l.fpga_a == 0
        and l.fpga_b == 1
        and l.width == 8
        and link_bandwidth_mbps(l) == 8000

    test serdes_link_creation
        given l = serdes_link(0, 1)
        then l.protocol == 1
        and link_bandwidth_mbps(l) == 25000

    test assignment_creation
        given a = assignment("uart", 0, 200, 100, 1, 0)
        then a.module_name == "uart"
        and a.fpga_idx == 0

    test partition_ok_creation
        given r = partition_ok(2, 5, 1, 8000)
        then r.num_fpgas == 2
        and r.balanced == true
        and passed(r) == true

    test partition_fail_creation
        given r = partition_fail(1)
        then passed(r) == false

    test total_link_bandwidth
        then total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 2) == 12000

    // count, not length, decides how much of the array is summed: the flat
    // array + count convention means a short count must ignore the tail.
    test total_link_bandwidth_respects_count
        then total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 1) == 8000
        and total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 0) == 0

    test fpga_util_calc
        given n = arty_a7_node("fpga0")
        then fpga_util(n, 31700) == 50

    test fpga_remaining_calc
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 10000) == 53400

    test fpga_remaining_over
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 100000) == 0

    test validate_node_ok
        given n = arty_a7_node("fpga0")
        then validate_node(n) == 0

    test validate_node_empty
        given n = FpgaNode{.name = "", .device = "xc7a100t", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then validate_node(n) > 0

    // Both faults are counted, not just the first one found.
    test validate_node_counts_every_fault
        given n = FpgaNode{.name = "", .device = "xc7a100t", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then validate_node(n) == 2

    // The three ends of the utilisation range.
    test fpga_util_endpoints
        given n = arty_a7_node("fpga0")
        then fpga_util(n, 0) == 0
        and fpga_util(n, 63400) == 100

    // A zero-LUT node would divide by zero; the guard returns 0 instead.
    test fpga_util_zero_lut_node
        given n = FpgaNode{.name = "empty", .device = "none", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then fpga_util(n, 1000) == 0

    // Exactly full is 0 remaining, not an underflow.
    test fpga_remaining_exact_fit
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 63400) == 0
        and fpga_remaining(n, 0) == 63400

    // used + remaining == capacity, for any load within capacity.
    test fpga_remaining_complements_use
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 20000) + 20000 == n.luts

    // partition_fail carries the error count through and never reports passed.
    test partition_fail_carries_count
        given r = partition_fail(3)
        then r.errors == 3
        and r.balanced == false
        and r.num_fpgas == 0
        and passed(r) == false

    // SERDES is 4 lanes at 6250 Mbps; the protocol tag separates it from LVDS.
    test serdes_link_shape
        given s = serdes_link(2, 3)
        and l = lvds_link(2, 3, 4)
        then s.width == 4
        and s.fpga_a == 2
        and s.fpga_b == 3
        and s.protocol != l.protocol

    // === Invariants ===

    invariant bandwidth_non_negative
        given l = lvds_link(0, 1, 8)
        assert link_bandwidth_mbps(l) >= 0

    invariant util_bounded
        given n = arty_a7_node("inv")
        assert fpga_util(n, 0) == 0

    bench fpga_util_latency
        measure: nanoseconds to fpga_util(arty_a7_node("bench"), 15850)
        target: < 50ns

    bench link_bandwidth_latency
        measure: nanoseconds to link_bandwidth_mbps(lvds_link(0, 1, 8))
        target: < 50ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
; 01 — Values and types
; Lesson 1 of the t27 tutorial. Every constant carries an explicit width,
; because a spec has to say what reaches hardware rather than let a compiler
; pick for it. Nothing here is inferred.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-01-values;

// ============================================================================
// Integers
//
// Width and signedness are part of the name's type, always written out.
// u = unsigned, i = signed, and the number is the bit width.
// ============================================================================

pub const SMALL_UNSIGNED : u8 = 200;
pub const SMALL_SIGNED : i8 = -100;
pub const WIDE_UNSIGNED : u16 = 65535;
pub const WIDER : u32 = 4000000000;
pub const SIGNED_32 : i32 = -2000000;

// ============================================================================
// Other bases
//
// Hex and binary are ordinary integer literals. Binary is worth using wherever
// the value IS a bit pattern -- a mask written as 0b111111111 documents its own
// width in a way that 511 does not.
// ============================================================================

pub const AS_HEX : u16 = 0xFFFF;
pub const AS_BINARY : u8 = 0b1010;
pub const MANTISSA_MASK : u16 = 0b111111111;

// ============================================================================
// Floats and booleans
// ============================================================================

pub const RATIO : f32 = 1.5;
pub const PRECISE : f64 = 2.25;

pub const ENABLED : bool = true;
pub const DISABLED : bool = false;

// ============================================================================
// The trit
//
// This language is built on three states rather than two. A trit is stored in
// an i8 and is only ever -1, 0 or +1; the invariant at the bottom is what
// makes that a claim rather than a comment.
// ============================================================================

pub const TRIT_NEG : i8 = -1;
pub const TRIT_ZERO : i8 = 0;
pub const TRIT_POS : i8 = 1;

pub const TRINITY : i8 = 3;

// ============================================================================
// Invariants
//
// An invariant states something that must hold for the module as a whole. It
// is checked, not decorative.
// ============================================================================

invariant trit_range_is_three_states
    assert TRIT_POS - TRIT_NEG + 1 == TRINITY

invariant masks_match_their_widths
    assert MANTISSA_MASK == 511
